#!/usr/bin/env python3
"""
NewsHub Feishu - 飞书推送
"""
import sys
sys.path.insert(0, str(__file__.rsplit('/', 1)[0] if '/' in __file__ else '.'))
from news_fetcher import fetch_all, load_config, filter_new

sys.path.insert(0, r'D:\OpenClaw\workspace\30-scripts-tools\feishu-tools')
from feishu_api import FeishuAPIClient

from datetime import datetime
from pathlib import Path
import json

BASE_DIR = Path(r'D:\OpenClaw\workspace\30-scripts-tools')
HISTORY_FILE = BASE_DIR / "news_history.json"


def load_history():
    if HISTORY_FILE.exists():
        with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return []


def save_history(hist):
    with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
        json.dump(hist, f, ensure_ascii=False)


def push_to_feishu(news_items):
    """推送到飞书"""
    client = FeishuAPIClient()

    for item in news_items:
        card = {
            "msg_type": "interactive",
            "card": {
                "config": {"wide_screen_mode": True},
                "header": {
                    "title": {"tag": "plain_text", "content": f"📰 {item['source']}"},
                    "template": "blue"
                },
                "elements": [
                    {"tag": "div", "text": {"tag": "lark_md", "content": f"**{item['title']}**"}},
                    {"tag": "hr"},
                    {"tag": "action", "actions": [
                        {"tag": "open_url", "text": {"tag": "lark_md", "content": "🔗 查看详情"}, "url": item['url']}
                    ]}
                ]
            }
        }
        client.send_card(card)


def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "all"
    config = load_config()
    keywords = config.get('keywords', [])

    print(f"[{datetime.now().strftime('%H:%M:%S')}] [Feishu] Mode: {mode}")

    # 抓取
    print("[Feishu] Fetching news...")
    all_news = fetch_all()
    print(f"[Feishu] Fetched {len(all_news)} items")

    if not all_news:
        print("[Feishu] No news")
        return

    # 去重
    history = load_history()
    new_news = [n for n in all_news if n['title'] not in history]
    print(f"[Feishu] New: {len(new_news)} items")

    if not new_news:
        print("[Feishu] No new news")
        return

    # 根据模式处理
    if mode == "alert":
        items = [n for n in new_news if any(kw in n['title'] for kw in keywords)]
        print(f"[Feishu] Alerts: {len(items)}")
    elif mode == "digest":
        items = new_news[:5]
    else:
        items = new_news[:10]

    if items:
        push_to_feishu(items)
        # 更新历史
        for n in items:
            history.append(n['title'])
        save_history(history[-1000:])  # 保留最近1000条
        print(f"[Feishu] ✅ Sent {len(items)} items")
    else:
        print("[Feishu] No items to send")


if __name__ == "__main__":
    main()

