#!/usr/bin/env python3
"""
NewsHub QQ - QQ推送 (NapCat)
"""
import sys
sys.path.insert(0, str(__file__.rsplit('/', 1)[0] if '/' in __file__ else '.'))
from news_fetcher import fetch_all, load_config

sys.stdout.reconfigure(encoding='utf-8')

from pathlib import Path
import json
import ssl
import time
import urllib.request

CONFIG_FILE = Path(__file__).parent / "qq_config.json"
HISTORY_FILE = Path(__file__).parent / "qq_history.json"


def load_config():
    with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
        return json.load(f)


def load_history():
    if HISTORY_FILE.exists():
        with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {"sent": []}


def save_history(hist):
    with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
        json.dump(hist, f, ensure_ascii=False)


def api_request(url, data, method='POST'):
    cfg = load_config()
    req = urllib.request.Request(url, data=json.dumps(data).encode(), headers={
        'Content-Type': 'application/json',
        'Authorization': f"Bearer {cfg.get('token', '')}"
    }, method=method)

    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE

    with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
        return json.loads(r.read())


def send_group_msg(group_id, msg):
    cfg = load_config()
    url = f"{cfg['base_url']}/send_group_msg"
    return api_request(url, {"group_id": group_id, "message": msg, "auto_escape": False})


def build_news_msg(news_list):
    lines = ["📊 金十快讯"]
    lines.append("─" * 16)
    for i, n in enumerate(news_list[:8], 1):
        lines.append(f"{i}. {n['title'][:35]}...")
    lines.append("─" * 16)
    return '\n'.join(lines)


def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "status"
    cfg = load_config()

    if not cfg.get('enable', False):
        print("QQ push disabled (enable=false in qq_config.json)")
        return

    group_id = cfg.get('group_id')

    if mode == "test":
        try:
            login = api_request(f"{cfg['base_url']}/get_login_info", {})
            print(f"Connected! QQ: {login.get('data', {}).get('nickname')}")
            send_group_msg(group_id, "NewsHub Test OK")
            print("Test message sent")
        except Exception as e:
            print(f"Error: {e}")

    elif mode == "jin10":
        news = fetch_all()
        hist = load_history()
        new_news = [n for n in news if n['title'] not in hist['sent']]

        if not new_news:
            print("No new news")
            return

        print(f"Fetched {len(news)}, {len(new_news)} new")

        for n in new_news[:5]:
            msg = f"📰 {n['title']}\n🔗 {n['url']}"
            try:
                send_group_msg(group_id, msg)
                hist['sent'].append(n['title'])
                print(f"  Sent: {n['title'][:40]}...")
                time.sleep(0.5)
            except Exception as e:
                print(f"  Error: {e}")
                break

        save_history(hist)
        print(f"Done: {min(5, len(new_news))} items")

    elif mode == "digest":
        news = fetch_all()
        msg = build_news_msg(news)
        send_group_msg(group_id, msg)
        print("Digest sent")

    elif mode == "status":
        try:
            info = api_request(f"{cfg['base_url']}/get_login_info", {})
            hist = load_history()
            print(f"QQ: {info.get('data', {}).get('nickname')}")
            print(f"Sent: {len(hist['sent'])} items")
        except Exception as e:
            print(f"Error: {e}")

    else:
        print(f"Usage: python {sys.argv[0]} [test|jin10|digest|status]")


if __name__ == "__main__":
    main()

