    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {}


def load_history():
    if HISTORY_FILE.exists():
        with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return []


def save_history(hist):
    with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
        json.dump(hist, f, ensure_ascii=False)


def send_card(webhook, card):
    """发送卡片消息"""
    req = urllib.request.Request(
        webhook,
        data=json.dumps(card).encode('utf-8'),
        headers={'Content-Type': 'application/json'},
        method='POST'
    )
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE

    with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
        return json.loads(r.read())


def build_card(title, news_url):
    """构建飞书卡片"""
    return {
        "msg_type": "interactive",
        "card": {
            "config": {"wide_screen_mode": True},
            "header": {
                "title": {"tag": "plain_text", "content": title},
                "template": "blue"
            },
            "elements": [
                {"tag": "div", "text": {"tag": "lark_md", "content": f"[查看详情]({news_url})"}}
            ]
        }
    }


def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "all"
    config = load_config()
    feishu = load_feishu_config()

    webhook = feishu.get('webhook', '')
    if not webhook:
        print("No Feishu webhook configured")
        return

    print(f"[{datetime.now().strftime('%H:%M:%S')}] Feishu: {mode}")

    # 抓取
    all_news = fetch_all()
    print(f"Fetched: {len(all_news)} items")

    if not all_news:
        return

    # 去重
    history = load_history()
    new_news = [n for n in all_news if n['title'] not in history]
    print(f"New: {len(new_news)}")

    if not new_news:
        print("No new news")
        return

    # 发送
    keywords = config.get('keywords', [])

    if mode == "alert":
        items = [n for n in new_news if any(kw in n['title'] for kw in keywords)]
    elif mode == "digest":
        items = new_news[:5]
    else:
        items = new_news[:10]

    if not items:
