#!/usr/bin/env python3
"""
NewsHub Feishu - 飞书推送 (完整版)
"""
import sys
sys.stdout.reconfigure(encoding='utf-8')
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent))
from news_fetcher import fetch_all, load_config

from datetime import datetime
import json
import ssl
import time
import urllib.request

BASE_DIR = Path(r'D:\OpenClaw\workspace\30-scripts-tools')
CONFIG_FILE = BASE_DIR / "feishu-tools" / "feishu-config.json"
HISTORY_FILE = BASE_DIR / "news_history.json"

def info(msg): print(f"  ▶ {msg}")
def ok(msg): print(f"  ✓ {msg}")
def warn(msg): print(f"  ⚠ {msg}")
def error(msg): print(f"  ✗ {msg}")

def banner(title):
    print()
    print("=" * 50)
    print(f"  {title}")
    print("=" * 50)
    print()


def load_feishu_config():
    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {}


def load_history():
    if HISTORY_FILE.exists():
        with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data if isinstance(data, list) else data.get('sent', [])
    return []


def save_history(hist):
    with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
        json.dump(hist[-1000:], f, ensure_ascii=False)


def get_access_token():
    cfg = load_feishu_config()
    url = "https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal"
    data = {"app_id": cfg['app_id'], "app_secret": cfg['app_secret']}

    req = urllib.request.Request(url, data=json.dumps(data).encode(), 
                                  headers={'Content-Type': 'application/json'}, method='POST')
    ctx = ssl.create_default_context()

    with urllib.request.urlopen(req, timeout=10, context=ctx) as r:
        result = json.loads(r.read())
        return result.get('tenant_access_token', '')


def build_news_card(title, url, source="", time_str=""):
    """单条新闻卡片"""
    return {
        "header": {
            "title": {"tag": "plain_text", "content": source or "NewsHub"},
            "template": "blue"
        },
        "elements": [
            {"tag": "div", "text": {"tag": "plain_text", "content": title}},
            {"tag": "hr"},
            {
                "tag": "action",
                "actions": [
                    {"tag": "open_url", "text": {"tag": "plain_text", "content": "查看详情"}, "url": url}
                ]
            },
            {"tag": "div", "text": {"tag": "plain_text", "content": time_str or datetime.now().strftime("%H:%M")}}
        ]
    }


def build_digest_card(news_list):
    """摘要卡片"""
    items = []
    for i, n in enumerate(news_list[:6], 1):
        title = n['title'][:35] + "..." if len(n['title']) > 35 else n['title']
        source = n.get('source', '')
        # 使用 markdown 格式
        items.append({
            "tag": "markdown",
            "content": f"**{i}.** {title}  \n> {source}"
        })

    time_str = datetime.now().strftime("%Y-%m-%d %H:%M")

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"财经速报 {time_str}"},
            "template": "green"
        },
        "elements": [
            *items,
            {"tag": "hr"},
            {
                "tag": "note",
                "elements": [
                    {"tag": "plain_text", "content": "NewsHub · 自动推送"}
                ]
            }
        ]
    }


def build_alert_card(title, url, source="", keywords=None):
    """告警卡片 - 高亮关键词"""
    kw_list = keywords or []
    highlight = ""
    for kw in kw_list:
        if kw in title:
            highlight = f"🔔 关键词: {kw}"
            break

    return {
        "header": {
            "title": {"tag": "plain_text", "content": "⚠️ 重要告警"},
            "template": "red"
        },
        "elements": [
            {"tag": "div", "text": {"tag": "plain_text", "content": highlight}},
            {"tag": "div", "text": {"tag": "plain_text", "content": title}},
            {"tag": "hr"},
            {
                "tag": "action",
                "actions": [
                    {"tag": "open_url", "text": {"tag": "plain_text", "content": "查看详情"}, "url": url}
                ]
            }
        ]
    }


def build_daily_summary(all_news):
    """日报卡片"""
    # 按来源统计
    sources = {}
    for n in all_news:
        s = n.get('source', 'Other')
        sources[s] = sources.get(s, 0) + 1

    stats = "\n".join([f"- {s}: {c}条" for s, c in sources.items()])

    time_str = datetime.now().strftime("%Y-%m-%d")

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"📊 {time_str} 新闻日报"},
            "template": "purple"
        },
        "elements": [
            {"tag": "markdown", "content": f"**今日共 {len(all_news)} 条新闻**\n\n{stats}"},
            {"tag": "hr"},
            {"tag": "div", "text": {"tag": "plain_text", "content": "NewsHub · 自动生成"}}
        ]
    }


def send_card(token, receive_id, card):
    cfg = load_feishu_config()
    api_url = "https://open.feishu.cn/open-apis/im/v1/messages"
    params = f"?receive_id_type={cfg.get('receive_id_type', 'open_id')}"

    payload = {
        "receive_id": receive_id,
        "msg_type": "interactive",
        "content": json.dumps(card, ensure_ascii=False)
    }

    req = urllib.request.Request(
        api_url + params,
        data=json.dumps(payload, ensure_ascii=False).encode('utf-8'),
        headers={
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {token}'
        },
        method='POST'
    )

    ctx = ssl.create_default_context()
    try:
        with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        error(f"HTTP {e.code}: {e.read().decode()[:100]}")
        return {"code": e.code}


def cmd_all():
    config = load_config()
    feishu = load_feishu_config()
    history = load_history()

    all_news = fetch_all()
    if not all_news:
        warn("No news")
        return 0

    new_news = [n for n in all_news if n['title'] not in history]
    if not new_news:
        warn("No new news")
        return 0

    info(f"Total: {len(all_news)} | New: {len(new_news)}")
    print()

    items = new_news[:8]
    token = get_access_token()
    if not token:
        error("Failed to get token")
        return 0

    sent = 0
    for n in items:
        try:
            card = build_news_card(n['title'], n['url'], n.get('source', ''))
            result = send_card(token, feishu.get('default_receive_id', ''), card)
            if result.get('code') == 0:
                history.append(n['title'])
                ok(n['title'][:40] + "...")
                sent += 1
            else:
                error(f"Code {result.get('code')}")
            time.sleep(0.2)
        except Exception as e:
            error(str(e)[:50])
            break

    save_history(history)
    return sent


def cmd_alert():
    config = load_config()
    feishu = load_feishu_config()
    history = load_history()
    keywords = config.get('keywords', [])

    if not keywords:
        warn("No keywords configured")
        return 0

    all_news = fetch_all()
    if not all_news:
        warn("No news")
        return

