#!/usr/bin/env python3
"""
NewsHub Feishu - 飞书推送 (优化版)
"""
import sys
sys.stdout.reconfigure(encoding='utf-8')
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent))
from news_fetcher import fetch_all, load_config

from datetime import datetime
import json
import ssl
import time
import urllib.request

BASE_DIR = Path(r'D:\OpenClaw\workspace\30-scripts-tools')
CONFIG_FILE = BASE_DIR / "feishu-tools" / "feishu-config.json"
HISTORY_FILE = BASE_DIR / "news_history.json"

# 颜色定义
COLORS = {
    'blue': '🔵',
    'green': '🟢', 
    'red': '🔴',
    'purple': '🟣',
    'orange': '🟠',
    'gray': '⚪',
    'yellow': '🟡'
}

def info(msg): print(f"  {COLORS['blue']} {msg}")
def ok(msg): print(f"  {COLORS['green']} {msg}")
def warn(msg): print(f"  {COLORS['orange']} {msg}")
def error(msg): print(f"  {COLORS['red']} {msg}")

def banner(title, icon="📡"):
    print()
    print("╔" + "═" * 48 + "╗")
    print(f"  {icon} {title}")
    print("╚" + "═" * 48 + "╝")
    print()

def sep():
    print("  " + "─" * 46)

def stats(all_count, new_count, sources):
    print()
    print("  ┌─ 新闻统计 ─────────────────────────────┐")
    print(f"  │  📰 总数: {all_count:<6}  🆕 新: {new_count:<6}  │")
    print("  ├──────────────────────────────────────┤")
    for s, c in sources.items():
        icon = "🔹" if "金十" in s else ("🔸" if "Investing" in s else "🔶")
        print(f"  │  {icon} {s:<12} {c:>3} 条              │")
    print("  └──────────────────────────────────────┘")
    print()


def load_feishu_config():
    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {}


def load_history():
    if HISTORY_FILE.exists():
        with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data if isinstance(data, list) else data.get('sent', [])
    return []


def save_history(hist):
    with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
        json.dump(hist[-1000:], f, ensure_ascii=False)


def get_access_token():
    cfg = load_feishu_config()
    url = "https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal"
    data = {"app_id": cfg['app_id'], "app_secret": cfg['app_secret']}

    req = urllib.request.Request(url, data=json.dumps(data).encode(), 
                                  headers={'Content-Type': 'application/json'}, method='POST')
    ctx = ssl.create_default_context()

    with urllib.request.urlopen(req, timeout=10, context=ctx) as r:
        result = json.loads(r.read())
        return result.get('tenant_access_token', '')


def send_card(token, receive_id, card):
    cfg = load_feishu_config()
    api_url = "https://open.feishu.cn/open-apis/im/v1/messages"
    params = f"?receive_id_type={cfg.get('receive_id_type', 'open_id')}"

    payload = {
        "receive_id": receive_id,
        "msg_type": "interactive",
        "content": json.dumps(card, ensure_ascii=False)
    }

    req = urllib.request.Request(
        api_url + params,
        data=json.dumps(payload, ensure_ascii=False).encode('utf-8'),
        headers={
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {token}'
        },
        method='POST'
    )

    ctx = ssl.create_default_context()
    try:
        with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        error(f"HTTP {e.code}: {e.read().decode()[:80]}")
        return {"code": e.code}


# ═══════════════════════════════════════════════════════════════
# 卡片构建
# ═══════════════════════════════════════════════════════════════

def build_news_card(title, url, source="", time_str=""):
    """单条新闻卡片"""
    icon = "📰" if "金十" in source else ("📊" if "Investing" in source else "📱")
    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"{icon} {source}" if source else f"{icon} NewsHub"},
            "template": "blue"
        },
        "elements": [
            {"tag": "div", "text": {"tag": "lark_md", "content": title}},
            {"tag": "hr"},
            {"tag": "markdown", "content": f"[🔗 查看详情]({url})"},
            {"tag": "div", "text": {"tag": "lark_md", "content": f"🕐 {time_str or datetime.now().strftime('%H:%M')}"}}
        ]
    }


def build_digest_card(news_list):
    """摘要卡片 - 精选6条"""
    items = []
    for i, n in enumerate(news_list[:6], 1):
        title = n['title'][:32] + "..." if len(n['title']) > 32 else n['title']
        source = n.get('source', '')
        icon = "🔹" if "金十" in source else ("🔸" if "Investing" in source else "🔶")
        items.append({
            "tag": "markdown",
            "content": f"**{i}.** {title}\n> {icon} {source}"
        })

    time_str = datetime.now().strftime("%H:%M")

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"📊 财经速报 {time_str}"},
            "template": "green"
        },
        "elements": [
            *items,
            {"tag": "hr"},
            {"tag": "div", "text": {"tag": "lark_md", "content": "📱 NewsHub · 自动推送"}}
        ]
    }


def build_alert_card(title, url, source="", keywords=None):
    """告警卡片"""
    kw_list = keywords or []
    highlight = ""
    for kw in kw_list:
        if kw in title:
            highlight = f"🔔 命中: `{kw}`"
            break

    return {
        "header": {
            "title": {"tag": "plain_text", "content": "⚠️ 重要告警"},
            "template": "red"
        },
        "elements": [
            {"tag": "div", "text": {"tag": "lark_md", "content": highlight}},
            {"tag": "markdown", "content": f"**{title}**"},
            {"tag": "hr"},
            {"tag": "markdown", "content": f"[🔗 查看详情]({url})"}
        ]
    }


def build_daily_summary(all_news):
    """日报卡片"""
    sources = {}
    for n in all_news:
        s = n.get('source', 'Other')
        sources[s] = sources.get(s, 0) + 1

    # 计算趋势 (简化)
    lines = [f"📰 **今日共 {len(all_news)} 条新闻**"]
    lines.append("")
