        icon = "🔹" if "金十" in s else ("🔸" if "Investing" in s else "🔶")
        bar = "█" * min(c // 2, 15)
        lines.append(f"{icon} {s:<12} {c:>2} 条 {bar}")

    time_str = datetime.now().strftime("%Y-%m-%d")

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"📊 {time_str} 日报"},
            "template": "purple"
        },
        "elements": [
            {"tag": "markdown", "content": "\n".join(lines)},
            {"tag": "hr"},
            {"tag": "div", "text": {"tag": "lark_md", "content": "🤖 NewsHub · 自动生成"}}
        ]
    }


