        icon = "🔹" if "金十" in s else ("🔸" if "Investing" in s else "🔶")
        items.append({"tag": "markdown", "content": f"**{i}.** {title}\n> {icon} {s}"})
    return {"header": {"title": {"tag": "plain_text", "content": f"📊 财经速报 {datetime.now().strftime('%H:%M')}"}, "template": "green"}, "elements": [*items, {"tag": "hr"}, {"tag": "div", "text": {"tag": "lark_md

