#!/usr/bin/env python3
"""
NewsHub Core - 新闻抓取 (优化版)
- 并行抓取
- 缓存支持
- 快速模式
"""
import sys
import json
import ssl
import re
import time
import hashlib
import urllib.request
import xml.etree.ElementTree as ET
from datetime import datetime
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor, as_completed

sys.stdout.reconfigure(encoding='utf-8')
BASE_DIR = Path(__file__).parent
CONFIG_FILE = BASE_DIR / "sources.json"
CACHE_FILE = BASE_DIR / ".news_cache.json"

# 缓存 TTL: 5分钟
CACHE_TTL = 300

# ============================================================
# 缓存
# ============================================================

def load_cache():
    if CACHE_FILE.exists():
        try:
            with open(CACHE_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except:
            pass
    return {"data": [], "time": 0}

def save_cache(news):
    with open(CACHE_FILE, 'w', encoding='utf-8') as f:
        json.dump({"data": news, "time": time.time()}, f, ensure_ascii=False)

def get_cached(quiet=False):
    cache = load_cache()
    age = time.time() - cache.get('time', 0)
    if age < CACHE_TTL:
        if not quiet:
            print(f"  💾 缓存: {len(cache['data'])} 条 ({age:.0f}s前)")
        return cache.get('data', [])
    return None

# ============================================================
# 美化输出
# ============================================================

def info(msg): print(f"  ▶ {msg}")
def ok(msg): print(f"  ✓ {msg}")
def warn(msg): print(f"  ⚠ {msg}")
def error(msg): print(f"  ✗ {msg}")

def banner(title):
    print()
    print("=" * 50)
    print(f"  {title}")
    print("=" * 50)
    print()

def summary(total, sources, elapsed):
    print()
    print("─" * 50)
    print(f"  📊 Total: {total}  ⏱️ {elapsed:.1f}s")
    for name, count in sources.items():
        print(f"     {name}: {count}")
    print("─" * 50)
    print()

# ============================================================
# SSL
# ============================================================

def get_ssl():
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    return ctx

# ============================================================
# 金十快讯 (快速版)
# ============================================================

def fetch_jin10(limit=20):
    news = []
    try:
        req = urllib.request.Request("https://flash.jin10.com/", headers={
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        })
        with urllib.request.urlopen(req, timeout=10, context=get_ssl()) as r:
            content = r.read().decode('utf-8')

        # 快速提取: 直接从列表页提取标题
        items = re.findall(r'<div class="news-item[^"]*".*?<p class="text">(.*?)</p>', content, re.DOTALL)
        urls = re.findall(r'/detail/(\d{17,20})', content)

        for i, (url, title) in enumerate(zip(urls[:limit], items[:limit])):
            if not title or len(title) < 10:
                continue
            title = re.sub(r'<[^>]+>', '', title).strip()
            title = re.sub(r'^【金十数据】', '', title)
            if title:
                news.append({
                    "title": title,
                    "url": f"https://flash.jin10.com/detail/{url}",
                    "source": "金十快讯",
                    "ts": time.time()
                })
    except Exception as e:
        error(f"Jin10: {e}")
    return news

# ============================================================
# RSS 源
# ============================================================

def fetch_rss(url, name=""):
    news = []
    try:
        req = urllib.request.Request(url, headers={
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        })
        with urllib.request.urlopen(req, timeout=10, context=get_ssl()) as r:
            content = r.read().decode('utf-8')

        root = ET.fromstring(content)
        ns = {'dc': 'http://purl.org/dc/elements/1.1/'}

        for item in root.findall('.//item')[:10]:
            title = item.findtext('title', '')
            link = item.findtext('link', '')
            if title and link:
                news.append({
                    "title": title.strip(),
                    "url": link.strip(),
                    "source": name,
                    "ts": time.time()
                })
    except Exception as e:
        error(f"{name}: {e}")
    return news

# ============================================================
# 配置
# ============================================================

def load_config():
    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {"news_sources": {}}

# ============================================================
# 并行抓取
# ============================================================

def fetch_source(key, src):
    name = src.get('name', key)
    if key == 'jin10':
        return name, fetch_jin10(src.get('limit', 20))
    elif src.get('url'):
        return name, fetch_rss(src['url'], name)
    return name, []

def fetch_all(quiet=False, use_cache=True, parallel=True):
    config = load_config()

    # 检查缓存
    if use_cache:
        cached = get_cached(quiet)
        if cached:
            return cached

    start = time.time()
    all_news = []
    sources = {}

    if not quiet:
        banner("NewsHub Fetcher")
        info(f"Time: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        if not parallel:
            warn("串行模式")
        print()

    # 构建任务列表
    tasks = []
    for key, src in config.get('news_sources', {}).items():
        if src.get('enable', True):
            tasks.append((key, src))

    if parallel and len(tasks) > 1:
        # 并行抓取
        if not quiet:
            info(f"并行抓取 {len(tasks)} 个源...")

        with ThreadPoolExecutor(max_workers=min(len(tasks), 5)) as executor:
            futures = {executor.submit(fetch_source, k, s): (k, s) for k, s in tasks}

            for i, future in enumerate(as_completed(futures), 1):
                name, news = future.result()
                sources[name] = len(news)
                all_news.extend(news)
                if not quiet:
                    if news:
                        ok(f"{name}: +{len(news)}")
                    else:
                        warn(f"{name}: 0")
    else:
        # 串行抓取
        for key, src in tasks:
            name = src.get('name', key)
            if not quiet:
                info(f"Fetching {name}...")

            if key == 'jin10':
                news = fetch_jin10(src.get('limit', 20))
            else:
                news = fetch_rss(src.get('url', ''), name)

            sources[name] = len(news)
            all_news.extend(news)

            if not quiet:
                if news:
                    ok(f"{name}: +{len(news)}")
                else:
                    warn(f"{name}: 0")

    # 排序
    all_news.sort(key=lambda x: x.get('ts', 0), reverse=True)
    elapsed = time.time() - start

    # 保存缓存
    save_cache(all_news)

    if not quiet:
        summary(len(all_news), sources, elapsed)

    return all_news

# ============================================================
# 快速测试模式
# ============================================================

def fetch_quick():
    """只抓取金十快讯，用于快速测试"""
    start = time.time()
    news = fetch_jin10(10)
    print(f"  💨 快速: +{len(news)} 条 ({time.time()-start:.1f}s)")
    return news

# ============================================================
# 显示新闻
# ============================================================

def show_news(news, limit=10):
    for i, n in enumerate(news[:limit], 1):
        print(f"  {i}. {n.get('source', '')}")
        print(f"     {n['title'][:60]}...")
        print(f"     {n.get('url', '')}")

