#!/usr/bin/env python3
"""
NewsHub Core - 新闻抓取 (v1.3)
- 并行抓取
- 缓存支持
- 去重机制
- 多源金融新闻
"""
import sys
import json
import ssl
import re
import time
import hashlib
import urllib.request
import xml.etree.ElementTree as ET
from datetime import datetime
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor, as_completed

sys.stdout.reconfigure(encoding='utf-8')
BASE_DIR = Path(__file__).parent
CONFIG_FILE = BASE_DIR / "sources.json"
CACHE_FILE = BASE_DIR / ".news_cache.json"

# 缓存 TTL
CACHE_TTL = 300

# ============================================================
# 工具函数
# ============================================================

def normalize_text(text):
    """标准化文本用于去重比较"""
    text = re.sub(r'\s+', ' ', text)
    text = re.sub(r'[^\w\u4e00-\u9fff]', '', text)
    return text.lower()[:100]

def hash_title(title):
    """生成标题哈希用于去重"""
    return hashlib.md5(normalize_text(title).encode()).hexdigest()[:8]

def deduplicate(news_list):
    """基于标题相似度的去重"""
    seen = set()
    result = []
    for item in news_list:
        h = hash_title(item['title'])
        if h not in seen:
            seen.add(h)
            result.append(item)
    return result

def time_ago(ts):
    """返回相对时间"""
    age = time.time() - ts
    if age < 60:
        return f"{int(age)}s前"
    elif age < 3600:
        return f"{int(age/60)}m前"
    elif age < 86400:
        return f"{int(age/3600)}h前"
    else:
        return f"{int(age/86400)}d前"

# ============================================================
# 缓存
# ============================================================

def load_cache():
    if CACHE_FILE.exists():
        try:
            with open(CACHE_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except:
            pass
    return {"data": [], "time": 0}

def save_cache(news):
    with open(CACHE_FILE, 'w', encoding='utf-8') as f:
        json.dump({"data": news, "time": time.time()}, f, ensure_ascii=False)

def get_cached(quiet=False):
    cache = load_cache()
    age = time.time() - cache.get('time', 0)
    if age < CACHE_TTL:
        if not quiet:
            print(f"  💾 缓存: {len(cache['data'])} 条 ({time_ago(cache.get('time', 0))})")
        return cache.get('data', [])
    return None

# ============================================================
# 美化输出
# ============================================================

def info(msg): print(f"  ▶ {msg}")
def ok(msg): print(f"  ✓ {msg}")
def warn(msg): print(f"  ⚠ {msg}")
def error(msg): print(f"  ✗ {msg}")

def banner(title):
    print()
    print("=" * 50)
    print(f"  {title}")
    print("=" * 50)
    print()

def summary(total, sources, elapsed, dup_removed=0):
    print()
    print("─" * 50)
    print(f"  📊 Total: {total}", end="")
    if dup_removed > 0:
        print(f" (去重: -{dup_removed})", end="")
    print(f"  ⏱️ {elapsed:.1f}s")
    for name, count in sources.items():
        print(f"     {name}: {count}")
    print("─" * 50)
    print()

# ============================================================
# SSL
# ============================================================

def get_ssl():
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    return ctx

# ============================================================
# 新闻源
# ============================================================

