def fetch_all(quiet=False, use_cache=True, parallel=True, dedup=True):
    config = load_config()

    # 检查缓存
    if use_cache:
        cached = get_cached(quiet)
        if cached:
            return cached

    start = time.time()
    all_news = []
    sources = {}

    if not quiet:
        banner("NewsHub Fetcher")
        info(f"Time: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        print()

    # 构建任务列表
    tasks = []
    for key, src in config.get('news_sources', {}).items():
        if src.get('enable', True):
            tasks.append((key, src))

    if parallel and len(tasks) > 1:
        # 并行抓取
        if not quiet:
            info(f"并行抓取 {len(tasks)} 个源...")

        with ThreadPoolExecutor(max_workers=min(len(tasks), 5)) as executor:
            futures = {executor.submit(fetch_source, k, s): (k, s) for k, s in tasks}

            for future in as_completed(futures):
                name, news = future.result()
                sources[name] = len(news)
                all_news.extend(news)
                if not quiet:
                    if news:
                        ok(f"{name}: +{len(news)}")
                    else:
                        warn(f"{name}: 0")
    else:
        # 串行抓取
        for key, src in tasks:
            name = src.get('name', key)
            if not quiet:
                info(f"Fetching {name}...")

            news = fetch_source(key, src)[1]
            sources[name] = len(news)
            all_news.extend(news)

            if not quiet:
                if news:
                    ok(f"{name}: +{len(news)}")
                else:
                    warn(f"{name}: 0")

    # 去重
    original_count = len(all_news)
    if dedup:
        all_news = deduplicate(all_news)

    # 排序
    all_news.sort(key=lambda x: x.get('ts', 0), reverse=True)
    elapsed = time.time() - start

    # 保存缓存
    save_cache(all_news)

    if not quiet:
        dup_removed = original_count - len(all_news)
        summary(len(all_news), sources, elapsed, dup_removed)

    return all_news

def fetch_quick():
    """只抓取新浪财经，用于快速测试"""
    start = time.time()
    news = fetch_sina_news(10)
    print(f"  💨 快速: +{len(news)} 条 ({time.time()-start:.1f}s)")
    return news

def show_news(news, limit=10):
    for i, n in enumerate(news[:limit], 1):
        print(f"  {i}. {n.get('source', '')}")
        print(f"     {n['title'][:60]}...")
        print(f"     {n.get('url', '')}")

def export_json(news, filename="news_export.json"):
    """导出为JSON"""
    with open(BASE_DIR / filename, 'w', encoding='utf-8') as f:
        json.dump(news, f, ensure_ascii=False, indent=2)
    print(f"  📄 导出: {filename} ({len(news)} 条)")

def export_csv(news, filename="news_export.csv"):
    """导出为CSV"""
    import csv
    with open(BASE_DIR / filename, 'w', encoding='utf-8-sig', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['序号', '标题', '来源', '类别', 'URL'])
        for i, n in enumerate(news, 1):
            writer.writerow([i, n.get('title', ''), n.get('source', ''), n.get('category', ''), n.get('url', '')])
    print(f"  📄 导出: {filename} ({len(news)} 条)")

# ============================================================
# 主程序
