if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description='NewsHub Fetcher')
    parser.add_argument('--quick', action='store_true', help='快速模式')
    parser.add_argument('--no-cache', action='store_true', help='禁用缓存')
    parser.add_argument('--cache-only', action='store_true', help='仅使用缓存')
    parser.add_argument('--no-dedup', action='store_true', help='禁用去重')
    parser.add_argument('--export', choices=['json', 'csv'], help='导出格式')
    parser.add_argument('--limit', type=int, default=50, help='最多返回条数')
    args = parser.parse_args()

    if args.no_cache:
        CACHE_TTL = 0
    elif args.cache_only:
        CACHE_TTL = 999999

    if args.quick:
        news = fetch_quick()
