    cat_names = {"stock": "股市", "forex": "外汇", "commodity": "大宗商品", "macro": "宏观", "trade": "贸易", "tech": "科技", "china": "中国", "us": "美国"}
    cat_icons = {"stock": "📈", "forex": "💱", "commodity": "🛢️", "macro": "🏛️", "trade": "⚖️", "tech": "💻", "china": "🇨🇳", "us": "🇺🇸"}
    cat_name = cat_names.get(category, category)
    cat_icon = cat_icons.get(category, "📰")

    items = []
    for i, n in enumerate(news_list[:8], 1):
        title = n['title'][:35] + "..." if len(n['title']) > 35 else n['title']
        sent = n.get('sentiment', '')
        sent_icon = "🟢" if sent == 'positive' else ("🔴" if sent == 'negative' else "")
        s = n.get('source', '')
        items.append({"tag": "markdown", "content": f"**{i}.** {sent_icon} {title}\n> {s}"})

    return {"header": {"title": {"tag": "plain_text", "content": f"{cat_icon} {cat_name}要闻 {datetime.now().strftime('%H:%M')}"}, "template": "blue"}, "elements": [*items, {"tag": "hr"}, {"tag": "div", "text": {"tag": "lark_md", "content": f"📱 NewsHub · {len(news_list)}条"}}]}

def build_sentiment_card(pos_news, neg_news):
    """情感分析卡片"""
    items = []

    if pos_news:
        items.append({"tag": "markdown", "content": f"## 🟢 利好 ({len(pos_news)})"})
        for n in pos_news[:3]:
            title = n['title'][:40] + "..." if len(n['title']) > 40 else n['title']
            items.append({"tag": "markdown", "content": f"- {title}"})

    if neg_news:
        if items:
            items.append({"tag": "hr"})
        items.append({"tag": "markdown", "content": f"## 🔴 利空 ({len(neg_news)})"})
        for n in neg_news[:3]:
            title = n['title'][:40] + "..." if len(n['title']) > 40 else n['title']
            items.append({"tag": "markdown", "content": f"- {title}"})

    return {"header": {"title": {"tag": "plain_text", "content": f"💡 情感分析 {datetime.now().strftime('%H:%M')}"}, "template": "orange"}, "elements": items}"}

