def add_hot_topics(news_list):
    """为新闻列表添加热点标签"""
    hot_topics = detect_hot_topics(news_list)
    hot_words = {w for w, _ in hot_topics}

    for news in news_list:
        title = news.get('title', '')
        news['hot_topics'] = [w for w in hot_words if w in title]

    return hot_topics

def cluster_news(news_list, max_clusters=5, min_cluster_size=2):
    """新闻聚类 - 将相似新闻分组"""
    clusters = []
    used = set()

    # 获取热点词作为聚类中心
    hot_topics = detect_hot_topics(news_list, top_n=max_clusters)

    for topic_word, _ in hot_topics:
        cluster = []
        for i, news in enumerate(news_list):
            if i in used:
                continue
            title = news.get('title', '')
            if topic_word in title:
                cluster.append(news)
                used.add(i)

        if len(cluster) >= min_cluster_size:
            clusters.append({
                'topic': topic_word,
                'news': cluster,
                'count': len(cluster)
            })

    # 添加未分类的新闻
    uncategorized = [n for i, n in enumerate(news_list) if i not in used]
    if uncategorized:
        clusters.append({
            'topic': '其他',
            'news': uncategorized,
            'count': len(uncategorized)
        })

    return clusters

