"""
NewsHub 每日简报生成器
"""
import json
import time
from datetime import datetime
from pathlib import Path

def generate_html_report(news_list, title="NewsHub 每日简报"):
    """生成HTML简报"""
    now = datetime.now()
    date_str = now.strftime('%Y年%m月%d日 %H:%M')

    # 统计
    total = len(news_list)
    positive = sum(1 for n in news_list if n.get('sentiment') == 'positive')
    negative = sum(1 for n in news_list if n.get('sentiment') == 'negative')
    neutral = total - positive - negative

    # 分类统计
    cats = {}
    for n in news_list:
        cat = n.get('category', 'other')
        cats[cat] = cats.get(cat, 0) + 1

    # 来源统计
    sources = {}
    for n in news_list:
        src = n.get('source', 'Other')
        sources[src] = sources.get(src, 0) + 1

    # 热点词
    hot = []
    word_freq = {}
    stopwords = {'的', '了', '在', '是', '我', '有', '和', '就', '不', '人', '都', '一', '上', '也', '很', '到', '说', '要', '去', '你', '会'}

    import re
    for n in news_list:
        title_text = n.get('title', '')
        words = [w for w in re.findall(r'[\u4e00-\u9fff]{2,4}', title_text) if w not in stopwords]
        for w in words:
            word_freq[w] = word_freq.get(w, 0) + 1

    hot = sorted(word_freq.items(), key=lambda x: -x[1])[:10]

    html = f"""<!DOCTYPE html>
<html lang="zh">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{title} - {date_str}</title>
    <style>
        * {{ margin: 0; padding: 0; box-sizing: border-box; }}
        body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #0f172a; color: #e2e8f0; min-height: 100vh; padding: 20px; }}
        .container {{ max-width: 900px; margin: 0 auto; }}

        .header {{ background: linear-gradient(135deg, #1e3a5f 0%, #0f172a 100%); border-radius: 16px; padding: 30px; margin-bottom: 20px; border: 1px solid #334155; }}
        .header h1 {{ font-size: 28px; color: #fff; margin-bottom: 10px; }}
