"""
NewsHub 关键词订阅系统
用户自定义关键词，当匹配时自动推送
"""
import re
import json
import time
from pathlib import Path
from datetime import datetime
from difflib import SequenceMatcher

SUBSCRIPTIONS_FILE = Path("subscriptions.json")

# 默认订阅配置
DEFAULT_SUBSCRIPTIONS = {
    "watch": [
        # A股热点
        {"keyword": "涨停", "level": "high", "desc": "A股涨停"},
        {"keyword": "降息", "level": "critical", "desc": "降息政策"},
        {"keyword": "人民币", "level": "medium", "desc": "汇率"},
        # 美股
        {"keyword": "Nvidia", "level": "high", "desc": "英伟达"},
        {"keyword": "Tesla", "level": "medium", "desc": "特斯拉"},
        {"keyword": "AI", "level": "medium", "desc": "AI相关"},
        # 宏观
        {"keyword": "CPI", "level": "high", "desc": "通胀数据"},
        {"keyword": "FED", "level": "critical", "desc": "美联储"},
        {"keyword": "tariff", "level": "critical", "desc": "关税"},
        {"keyword": "Trump", "level": "high", "desc": "特朗普"},
        # 大宗商品
        {"keyword": "原油", "level": "medium", "desc": "油价"},
        {"keyword": "黄金", "level": "medium", "desc": "金价"},
        {"keyword": "oil", "level": "medium", "desc": "油价(EN)"},
        {"keyword": "gold", "level": "medium", "desc": "金价(EN)"},
    ]
}

def load_subscriptions():
    """加载订阅配置"""
    if SUBSCRIPTIONS_FILE.exists():
        with open(SUBSCRIPTIONS_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return DEFAULT_SUBSCRIPTIONS

def save_subscriptions(subs):
    """保存订阅配置"""
    with open(SUBSCRIPTIONS_FILE, 'w', encoding='utf-8') as f:
        json.dump(subs, f, ensure_ascii=False, indent=2)

def add_subscription(keyword, level="medium", desc=""):
    """添加订阅"""
    subs = load_subscriptions()
    if "watch" not in subs:
        subs["watch"] = []

    # 检查是否已存在
    for item in subs["watch"]:
        if item["keyword"].lower() == keyword.lower():
            return False

    subs["watch"].append({
        "keyword": keyword,
        "level": level,
        "desc": desc or keyword,
        "added_at": datetime.now().isoformat()
    })
    save_subscriptions(subs)
    return True

def remove_subscription(keyword):
    """移除订阅"""
    subs = load_subscriptions()
    if "watch" not in subs:
        return False

    original_len = len(subs["watch"])
    subs["watch"] = [s for s in subs["watch"] if s["keyword"].lower() != keyword.lower()]

    if len(subs["watch"]) < original_len:
        save_subscriptions(subs)
        return True
    return False

def match_news(news, subscriptions):
    """匹配新闻"""
    matched = []

    for sub in subscriptions:
        keyword = sub.get("keyword", "")
        if not keyword:
            continue

        for item in news:
            title = item.get("title", "").lower()

            # 精确匹配
