# Categories
CATS = {
    "stock":["A股","上证","深证","港股","美股","股价","涨停","跌停","大盘","指数"],
    "forex":["汇率","美元","欧元","人民币","外汇","货币"],
    "commodity":["原油","黄金","白银","铜","大宗商品","期货"],
    "macro":["GDP","CPI","PPI","非农","美联储","央行","加息","降息"],
    "trade":["关税","贸易","WTO","出口","进口","协议"],
    "tech":["AI","科技","芯片","半导体","互联网","5G","人工智能"],
    "china":["中国","北京","上海","两会","政策"],
    "us":["美国","华盛顿","拜登","特朗普","美联储"],
    "crypto":["比特币","以太坊","加密货币","区块链","BTC","ETH"],
    "energy":["能源","石油","天然气","新能源","光伏","风电"]
}

# Sentiment keywords
POSITIVE = ["涨","升","利多","利好","上涨","突破","牛市","超预期","增长","恢复","反弹","新高"]
NEGATIVE = ["跌","降","利空","下跌","崩盘","熊市","低于预期","萎缩","危机","风险","警告","制裁"]

def classify_news(title):
    tl = title.lower()
    for cat, keywords in CATS.items():
        if any(kw.lower() in tl for kw in keywords):
            return cat
    return "other"

def analyze_sentiment(title):
    tl = title.lower()
    pos = sum(1 for w in POSITIVE if w in tl)
    neg = sum(1 for w in NEGATIVE if w in tl)
    if pos > neg:
        return "positive", 20
    elif neg > pos:
        return "negative", -20
    return "neutral", 0

def detect_hot_topics(news_list, top_n=10):
    stopwords = {"的","了","在","是","和","就","不","都","一","上","也","很","到","说","将","已","被","对","为","于","从","这"}
    word_freq = {}
    for n in news_list:
        words = re.findall(r\'[\u4e00-\u9fff]{2,4}\', n.get("title", ""))
        for w in words:
            if w not in stopwords and len(w) >= 2:
                word_freq[w] = word_freq.get(w, 0) + 1
    return sorted(word_freq.items(), key=lambda x: -x[1])[:top_n]

def cluster_news(news_list, max_clusters=5):
    hot = detect_hot_topics(news_list, top_n=max_clusters)
    clusters, used = [], set()
    for word, _ in hot:
        cluster = []
        for i, n in enumerate(news_list):
            if i in used:
                continue
            if word in n.get("title", ""):
                cluster.append(n)
                used.add(i)
        if len(cluster) >= 2:
            clusters.append({"topic": word, "news": cluster, "count": len(cluster)})
    return clusters

