import sys; sys.stdout.reconfigure(encoding='utf-8')
import re, json, time, ssl
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
import urllib.request, xml.etree.ElementTree as ET
import hashlib

CACHE_FILE = '.news_cache.json'
CACHE_TTL = 300
LLM_CACHE_FILE = '.llm_cache.json'

# 分类关键词
CATEGORIES = {
    'stock': ['A股','上证','深证','港股','美股','股价','涨停','跌停','大盘','指数','股票'],
    'forex': ['汇率','美元','欧元','人民币','外汇','货币','日元','英镑'],
    'commodity': ['原油','黄金','白银','铜','大宗商品','期货','油价','贵金属'],
    'macro': ['GDP','CPI','PPI','非农','美联储','央行','加息','降息','利率','通胀'],
    'trade': ['关税','贸易','WTO','出口','进口','协议','制裁'],
    'tech': ['AI','科技','芯片','半导体','互联网','5G','人工智能','区块链'],
    'china': ['中国','北京','上海','两会','政策','国务院'],
    'us': ['美国','华盛顿','拜登','特朗普','白宫'],
    'crypto': ['比特币','以太坊','加密货币','区块链','BTC','ETH','数字货币'],
    'energy': ['能源','石油','天然气','新能源','光伏','风电','煤炭']
}

# 情感词
POSITIVE = ['涨','升','利多','利好','上涨','突破','牛市','超预期','增长','盈利']
NEGATIVE = ['跌','降','利空','下跌','崩盘','熊市','低于预期','萎缩','亏损','暴跌']

def get_ssl_context():
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    return ctx

def load_cache():
    try:
        with open(CACHE_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {'news': [], 'time': 0}

def save_cache(data):
    with open(CACHE_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

def load_config():
    try:
        with open('config.json', 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {}

def classify_news(title):
    title_lower = title.lower()
    for cat, keywords in CATEGORIES.items():
        if any(kw.lower() in title_lower for kw in keywords):
            return cat
    return 'other'

def analyze_sentiment(title):
    title_lower = title.lower()
    pos = sum(1 for w in POSITIVE if w in title_lower)
    neg = sum(1 for w in NEGATIVE if w in title_lower)
    if pos > neg:
        return 'positive', 20
    elif neg > pos:
        return 'negative', -20
    return 'neutral', 0

def fetch_sina():
    news = []
    try:
        url = 'https://feed.mix.sina.com.cn/api/roll/get?pageid=153&lid=2516&k=&num=15&page=1&r=0.5'
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0', 'Referer': 'https://finance.sina.com.cn'})
        with urllib.request.urlopen(req, timeout=10, context=get_ssl_context()) as resp:
            data = json.loads(resp.read().decode('utf-8'))
            for item in data.get('result', {}).get('data', [])[:15]:
                title = item.get('title', '').strip()
                if title:
                    n = {'title': title, 'url': item.get('url', ''), 'source': '新浪财经', 'ts': time.time()}
                    n['category'] = classify_news(title)
                    n['sentiment'], n['score'] = analyze_sentiment(title)
                    news.append(n)
    except Exception as e:
        print(f'  ⚠ 新浪失败: {e}')
    return news

def fetch_eastmoney():
    news = []
    try:
        url = 'https://feed.eastmoney.com/more?type=globalnews&pageSize=10&page=1'
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=10, context=get_ssl_context()) as resp:
            data = json.loads(resp.read().decode('utf-8-sig'))
            for item in data.get('data', {}).get('list', [])[:10]:
                title = item.get('title', '').strip()
                if title:
                    n = {'title': title, 'url': f\"https://www.eastmoney.com/a/{item.get('id', '')}\", 'source': '东方财富', 'ts': time.time()}
                    n['category'] = classify_news(title)
                    n['sentiment'], n['score'] = analyze_sentiment(title)
                    news.append(n)
    except:
        pass
    return news

def fetch_ths():
    news = []
    try:
        url = 'https://news.10jqka.com.cn/tapp/news/pnews/'
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0', 'Referer': 'https://www.10jqka.com.cn'})
        with urllib.request.urlopen(req, timeout=10, context=get_ssl_context()) as resp:
            data = json.loads(resp.read().decode('utf-8'))
            for item in data.get('data', [])[:10]:
                title = item.get('title', '').strip()
                if title:
                    n = {'title': title, 'url': item.get('share_url', ''), 'source': '同花顺', 'ts': time.time()}
                    n['category'] = classify_news(title)
                    n['sentiment'], n['score'] = analyze_sentiment(title)
                    news.append(n)
    except:
        pass
    return news

def fetch_rss(url, name, limit=10):
    news = []
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=10, context=get_ssl_context()) as resp:
            root = ET.fromstring(resp.read().decode('utf-8'))
            for item in root.findall('.//item')[:limit]:
                title = item.findtext('title', '').strip()
                link = item.findtext('link', '')
                if title and link:
                    n = {'title': title, 'url': link, 'source': name, 'ts': time.time()}
                    n['category'] = classify_news(title)
                    n['sentiment'], n['score'] = analyze_sentiment(title)
                    news.append(n)
    except:
        pass
    return news

SOURCES = [
    ('新浪财经', fetch_sina),
    ('东方财富', fetch_eastmoney),
    ('同花顺', fetch_ths),
    ('Investing', lambda: fetch_rss('https://www.investing.com/rss/news.rss', 'Investing', 10)),
    ('CNBC', lambda: fetch_rss('https://www.cnbc.com/id/10000664/device/rss/rss.html', 'CNBC', 15)),
]

def fetch_all(quiet=False):
    cache = load_cache()
    if cache.get('news') and time.time() - cache.get('time', 0) < CACHE_TTL:
        if not quiet:
            print(f'  💾 缓存: {len(cache[\"news\"])} 条 ({int((time.time()-cache.get(\"time\",0))/60)}m前)')
        return cache['news']

    results = []
    start = time.time()
    if not quiet:
        print('  ▶ 并行抓取...')

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = {executor.submit(src['func'] if isinstance(src, dict) else src[1]): src['name'] if isinstance(src, dict) else src[0] for src in SOURCES}
        for future in futures:
            name = futures[future]
            try:
                news = future.result()
                results.extend(news)
                if not quiet:
                    print(f'  ✓ {name}: +{len(news)}')
            except Exception as e:
                if not quiet:
                    print(f'  ⚠ {name}: 失败')

    save_cache({'news': results, 'time': time.time()})
    elapsed = time.time() - start
    if not quiet:
        print(f'  ⏱️ {elapsed:.1f}s | {len(results)}条')
    return results

def detect_hot_topics(news_list, top_n=5):
    stopwords = {'的','了','在','是','和','就','不','都','一','上','也','很','到','说','有','这','那','要','会','对','为','能','可','与','及','等'}
    word_freq = {}
    for n in news_list:
        words = re.findall(r'[\\u4e00-\\u9fff]{2,4}', n.get('title', ''))
        for w in words:
            if w not in stopwords and len(w) >= 2:
                word_freq[w] = word_freq.get(w, 0) + 1
    return sorted(word_freq.items(), key=lambda x: -x[1])[:top_n]

def cluster_news(news_list, max_clusters=5):
    hot = detect_hot_topics(news_list, top_n=max_clusters)
    clusters = []
    used = set()
    for word, count in hot:
        cluster = []
        for i, n in enumerate(news_list):
            if i in used:
                continue
            if word in n.get('title', ''):
                cluster.append(n)
                used.add(i)
        if len(cluster) >= 2:
            clusters.append({'topic': word, 'news': cluster, 'count': len(cluster)})
    return clusters

def get_market_sentiment(news_list):
