#!/usr/bin/env python3
"""NewsHub LLM Enhanced Analyzer v3.0 - 智能新闻分析引擎"""
import json
import time
import ssl
import urllib.request
import re
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime

# ============================================================
# 配置
# ============================================================

OLLAMA_URL = "http://localhost:11434/api/generate"
MODEL = "qwen2.5:1.5b"
TIMEOUT = 30

# ============================================================
# 核心 LLM 调用
# ============================================================

def call_llm(prompt: str, max_tokens: int = 256) -> str:
    """调用 Ollama LLM"""
    try:
        data = json.dumps({
            "model": MODEL,
            "prompt": prompt,
            "stream": False,
            "options": {
                "num_predict": max_tokens,
                "temperature": 0.2
            }
        }).encode('utf-8')

        req = urllib.request.Request(
            OLLAMA_URL,
            data=data,
            headers={"Content-Type": "application/json"}
        )

        with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
            result = json.loads(resp.read().decode('utf-8'))
            return result.get('response', '').strip()
    except Exception as e:
        return f"[LLM Error: {e}]"

# ============================================================
# 增强分析函数
# ============================================================

def analyze_news(title: str, content: str = "") -> dict:
    """
    全面新闻分析
    返回: {
        'summary': str,      # 一句话总结
        'key_points': list,  # 关键要点
        'sentiment': int,    # 情感分数 (-100 到 +100)
        'confidence': int,   # 置信度 (0-100)
        'impact': str,       # 影响等级 (high/medium/low)
        'sectors': list,     # 影响板块
        'entities': dict,    # 实体识别
        'risk': dict,        # 风险评估
        'action': str        # 建议行动
    }
    """
    text = f"标题: {title}\n内容: {content[:300]}" if content else f"标题: {title}"

    # 1. 快速分析 (一次调用获取多个信息)
    quick_prompt = f"""分析这条财经新闻，用JSON格式回复：

{text}

返回格式（不要其他内容）:
{{"sentiment": 情感分数-100到+100, "impact": "high/medium/low", "summary": "一句话总结"}}

JSON:"""

    quick_result = call_llm(quick_prompt, 128)

    try:
        # 提取 JSON
        json_match = re.search(r'\{[^}]+\}', quick_result)
        if json_match:
            quick_data = json.loads(json_match.group())
        else:
            quick_data = {'sentiment': 0, 'impact': 'low', 'summary': title[:30]}
    except:
        quick_data = {'sentiment': 0, 'impact': 'low', 'summary': title[:30]}

    # 2. 实体识别
    entity_prompt = f"""提取新闻中的实体，JSON格式：
{text}
返回: {{"companies": ["公司名"], "sectors": ["板块"], "people": ["人名"]}}
JSON:"""

    entity_result = call_llm(entity_prompt, 128)
    try:
        json_match = re.search(r'\{[^}]+\}', entity_result)
        entities = json.loads(json_match.group()) if json_match else {}
    except:
        entities = {}

    # 3. 风险评估
    risk_prompt = f"""评估这条新闻的投资风险，JSON格式：
{text}
返回: {{"risk_level": "low/medium/high", "risk_type": "风险类型", "advice": "建议"}}
JSON:"""

    risk_result = call_llm(risk_prompt, 128)
    try:
        json_match = re.search(r'\{[^}]+\}', risk_result)
        risk = json.loads(json_match.group()) if json_match else {}
    except:
        risk = {}

    # 4. 提取关键要点
    points_prompt = f"""提取这条新闻的3个关键要点，用短句：
{text}
要点（每行一个）:"""

    points_result = call_llm(points_prompt, 128)
    key_points = [p.strip('- ').strip() for p in points_result.split('\n') if p.strip()][:3]

    return {
        'summary': quick_data.get('summary', title[:30]),
        'key_points': key_points,
        'sentiment': quick_data.get('sentiment', 0),
        'confidence': 75 if quick_data.get('summary') else 50,
        'impact': quick_data.get('impact', 'low'),
        'sectors': entities.get('sectors', []),
        'entities': entities,
        'risk': risk,
        'action': _get_action(quick_data.get('sentiment', 0), risk.get('risk_level', 'low'))
    }

def _get_action(sentiment: int, risk_level: str) -> str:
    """生成行动建议"""
    if risk_level == 'high':
        return '⚠️ 谨慎观望'
    elif sentiment > 50:
        return '📈 积极关注'
    elif sentiment < -50:
        return '📉 风险规避'
    else:
        return '👁️ 持续观察'

# ============================================================
# 批量分析
# ============================================================

def analyze_batch(news_list: list, max_workers: int = 5) -> list:
    """并行分析多条新闻"""
    results = []

    def analyze_one(item):
        title = item.get('title', '')
        content = item.get('content', item.get('summary', ''))
        analysis = analyze_news(title, content)
        return {**item, 'analysis': analysis}

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        results = list(executor.map(analyze_one, news_list))

    return results

# ============================================================
# 新闻去重
# ============================================================

def dedup_news(news_list: list, threshold: float = 0.7) -> list:
    """基于语义相似度去重"""
    if len(news_list) < 2:
        return news_list

    # 简单去重：标题关键词重合度
    unique = []
    seen_keywords = set()

    for news in news_list:
        title = news.get('title', '')
        keywords = set(title)

        # 计算与已选新闻的重合度
        overlap = 0
        for kw_set in [set(n.get('title', '')) for n in unique]:
            common = len(keywords & kw_set)
            total = max(len(keywords), len(kw_set))
            if total > 0:
                overlap = max(overlap, common / total)

        if overlap < threshold:
            unique.append(news)

    return unique

# ============================================================
# 智能排序
# ============================================================

def rank_news(news_list: list) -> list:
    """按重要性排序"""
    def score(news):
        analysis = news.get('analysis', {})
        sentiment = abs(analysis.get('sentiment', 0))
        impact = {'high': 30, 'medium': 15, 'low': 5}.get(analysis.get('impact', 'low'), 5)
        confidence = analysis.get('confidence', 50) / 10
        return sentiment + impact + confidence

    return sorted(news_list, key=score, reverse=True)

# ============================================================
# 市场情绪分析
# ============================================================

def market_sentiment(analyzed_news: list) -> dict:
    """计算市场整体情绪"""
    if not analyzed_news:
        return {'score': 0, 'label': '中性', 'distribution': {}}

    sentiments = [n.get('analysis', {}).get('sentiment', 0) for n in analyzed_news]
    avg = sum(sentiments) / len(sentiments)

    # 分布统计
    dist = {'positive': 0, 'neutral': 0, 'negative': 0}
    for s in sentiments:
        if s > 20:
            dist['positive'] += 1
        elif s < -20:
            dist['negative'] += 1
        else:
            dist['neutral'] += 1

    if avg > 30:
        label = '乐观'
    elif avg > 10:
        label = '偏乐观'
    elif avg < -30:
        label = '悲观'
    elif avg < -10:
        label = '偏悲观'
    else:
        label = '中性'

    return {
        'score': round(avg, 1),
        'label': label,
        'distribution': dist,
        'total': len(analyzed_news)
    }

# ============================================================
# 报告生成
# ============================================================

def generate_report(analyzed_news: list) -> str:
    """生成分析报告"""
    if not analyzed_news:
        return "无新闻数据"

    # 计算市场情绪
    sentiment = market_sentiment(analyzed_news)

    # 排序
    ranked = rank_news(analyzed_news)[:10]

    report = f"""
╔════════════════════════════════════════════════╗
║  📊 NewsHub 智能分析报告                            
╚════════════════════════════════════════════════╝

⏰ 时间: {datetime.now().strftime('%Y-%m-%d %H:%M')}

【市场情绪】
  指数: {sentiment['score']} ({sentiment['label']})
  分布: 📈{sentiment['distribution']['positive']} | ➖{sentiment['distribution']['neutral']} | 📉{sentiment['distribution']['negative']}

【重要新闻 TOP 5】
"""

    for i, news in enumerate(ranked[:5], 1):
        a = news.get('analysis', {})
        title = news.get('title', '')[:40]
        s = a.get('sentiment', 0)
        emoji = '🔴' if s < -20 else '🟢' if s > 20 else '⚪'
        impact = a.get('impact', 'low').upper()
        summary = a.get('summary', '')[:50]

        report += f"""
{i}. {emoji} [{impact}] {title}
   └ {summary}
"""

    # 风险提醒
    high_risk = [n for n in ranked if n.get('analysis', {}).get('risk', {}).get('risk_level') == 'high']
    if high_risk:
        report += f"\n【⚠️ 风险提醒】\n"
        for n in high_risk[:3]:
            risk = n.get('analysis', {}).get('risk', {})
            report += f"  • {n.get('title', '')[:35]}\n"
            report += f"    └ {risk.get('advice', '注意风险')}\n"

    return report

# ============================================================
# 测试
# ============================================================

if __name__ == "__main__":
    print("=" * 50)
    print("  NewsHub LLM Enhanced Analyzer v3.0")
    print("=" * 50)

    # 测试单条分析
    test_news = [
        {"title": "美联储宣布加息25个基点，美股应声下跌"},
        {"title": "中国新能源汽车出口创历史新高"},
        {"title": "某科技公司发布重大利好公告"}
    ]

    print("\n▶ 测试单条分析...")
    for news in test_news[:1]:
        result = analyze_news(news['title'])
        print(json.dumps(result, ensure_ascii=False, indent=2))

    print("\n▶ 测试批量分析...")
    analyzed = analyze_batch(test_news)

    print("\n▶ 测试报告生成...")
    report = generate_report(analyzed)
    print(report)

