    """基于标题相似度去重"""
    if len(news_list) < 2:
        return news_list

    def similarity(t1, t2):
        """计算两个标题的相似度"""
        words1 = set(t1)
        words2 = set(t2)
        if not words1 or not words2:
            return 0
        return len(words1 & words2) / max(len(words1), len(words2))

    unique = []
    for news in news_list:
        title = news.get('title', '')
        is_dup = False
        for u in unique:
            if similarity(title, u.get('title', '')) >= threshold:
                is_dup = True
                break
        if not is_dup:
            unique.append(news)

    return unique

