#!/usr/bin/env python3
"""NewsHub 微信企业推送"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import json
import urllib.request
import ssl
from pathlib import Path

# 配置文件
CONFIG_FILE = Path(__file__).parent / 'wechat_config.json'

def load_config():
    """加载配置"""
    try:
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {}

def send_markdown(webhook_url: str, content: str) -> bool:
    """发送 Markdown 消息"""
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        data = {
            "msgtype": "markdown",
            "markdown": {
                "content": content
            }
        }

        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(data).encode('utf-8'),
            headers={"Content-Type": "application/json"}
        )

        with urllib.request.urlopen(req, timeout=10, context=ctx) as resp:
            result = json.loads(resp.read().decode('utf-8'))
            return result.get('errcode', -1) == 0
    except Exception as e:
        print(f"发送失败: {e}")
        return False

def format_news_markdown(news_list: list, title: str = "📰 新闻速递") -> str:
    """格式化新闻为 Markdown"""
    lines = [f"## {title}", ""]

    for i, news in enumerate(news_list[:10], 1):
        n_title = news.get('title', '')[:50]
        source = news.get('source', '')
        url = news.get('url', '')

        if url:
            lines.append(f"**{i}.** [{n_title}]({url})")
        else:
            lines.append(f"**{i}.** {n_title}")
        lines.append(f"> 来源: {source}")
