#!/usr/bin/env python3
"""NewsHub Web Dashboard - 静态仪表盘生成器"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import json
from datetime import datetime
from pathlib import Path

DASHBOARD_FILE = Path(__file__).parent / 'dashboard.html'

def generate_dashboard(news_list: list, sentiment: dict = None, hot_topics: list = None) -> str:
    """生成仪表盘 HTML"""

    # 统计
    total = len(news_list)
    sources = {}
    categories = {}

    for n in news_list:
        src = n.get('source', 'unknown')
        sources[src] = sources.get(src, 0) + 1

        cat = n.get('category', 'other')
        categories[cat] = categories.get(cat, 0) + 1

    # 情感分布
    positive = sum(1 for n in news_list if n.get('score', 0) > 20)
    negative = sum(1 for n in news_list if n.get('score', 0) < -20)
    neutral = total - positive - negative

    html = f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>NewsHub Dashboard</title>
    <style>
        * {{ margin: 0; padding: 0; box-sizing: border-box; }}
        body {{ 
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            color: #e0e0e0;
            min-height: 100vh;
            padding: 20px;
        }}
        .container {{ max-width: 1400px; margin: 0 auto; }}

        /* Header */
        .header {{
            text-align: center;
            padding: 30px 0;
            border-bottom: 1px solid #333;
            margin-bottom: 30px;
        }}
        .header h1 {{ 
            font-size: 2.5em;
            background: linear-gradient(90deg, #00d2ff, #3a7bd5);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }}
        .header .time {{ color: #888; margin-top: 10px; }}

        /* Stats Cards */
        .stats {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }}
        .stat-card {{
            background: rgba(255,255,255,0.05);
            border-radius: 12px;
            padding: 20px;
            text-align: center;
            border: 1px solid rgba(255,255,255,0.1);
        }}
        .stat-card .value {{ 
            font-size: 2.5em;
            font-weight: bold;
            margin: 10px 0;
        }}
        .stat-card .label {{ color: #888; font-size: 0.9em; }}
        .stat-card.positive .value {{ color: #4caf50; }}
        .stat-card.negative .value {{ color: #f44336; }}
        .stat-card.neutral .value {{ color: #ff9800; }}

        /* News List */
        .news-section {{
            display: grid;
            grid-template-columns: 2fr 1fr;
            gap: 20px;
        }}
        .news-list {{
            background: rgba(255,255,255,0.05);
            border-radius: 12px;
            padding: 20px;
        }}
        .news-item {{
            padding: 15px 0;
            border-bottom: 1px solid rgba(255,255,255,0.1);
            display: flex;
            gap: 10px;
        }}
        .news-item:last-child {{ border-bottom: none; }}
        .news-sentiment {{
            width: 8px;
            border-radius: 4px;
            flex-shrink: 0;
        }}
        .news-sentiment.positive {{ background: #4caf50; }}
        .news-sentiment.negative {{ background: #f44336; }}
        .news-sentiment.neutral {{ background: #666; }}
        .news-content {{ flex: 1; }}
        .news-title {{ 
            font-size: 1em;
            margin-bottom: 5px;
            cursor: pointer;
        }}
        .news-title:hover {{ color: #00d2ff; }}
        .news-meta {{ font-size: 0.85em; color: #888; }}
        .news-source {{ 
            background: rgba(0,210,255,0.2);
            padding: 2px 8px;
            border-radius: 4px;
            font-size: 0.8em;
        }}

        /* Sidebar */
        .sidebar {{
            display: flex;
            flex-direction: column;
            gap: 20px;
        }}
        .sidebar-card {{
            background: rgba(255,255,255,0.05);
            border-radius: 12px;
            padding: 20px;
        }}
        .sidebar-card h3 {{
            margin-bottom: 15px;
            color: #00d2ff;
        }}
        .source-item {{
            display: flex;
            justify-content: space-between;
            padding: 8px 0;
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }}
        .hot-item {{
            padding: 10px 0;
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }}
        .hot-keyword {{ 
            font-weight: bold;
            color: #ff9800;
        }}
        .hot-count {{
            font-size: 0.85em;
            color: #888;
        }}

        /* Footer */
        .footer {{
            text-align: center;
            padding: 30px 0;
            color: #666;
            margin-top: 30px;
        }}

        @media (max-width: 768px) {{
            .news-section {{ grid-template-columns: 1fr; }}
        }}
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>📰 NewsHub</h1>
            <div class="time">最后更新: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}</div>
        </div>

        <div class="stats">
            <div class="stat-card">
                <div class="label">总新闻数</div>
                <div class="value">{total}</div>
            </div>
            <div class="stat-card positive">
                <div class="label">📈 正面</div>
                <div class="value">{positive}</div>
            </div>
            <div class="stat-card neutral">
                <div class="label">➖ 中性</div>
                <div class="value">{neutral}</div>
            </div>
            <div class="stat-card negative">
                <div class="label">📉 负面</div>
                <div class="value">{negative}</div>
            </div>
        </div>

        <div class="news-section">
            <div class="news-list">
                <h3 style="margin-bottom: 20px; color: #00d2ff;">最新新闻</h3>
"""

    # 添加新闻列表
    for news in news_list[:30]:
        score = news.get('score', 0)
        if score > 20:
            sentiment_class = 'positive'
        elif score < -20:
            sentiment_class = 'negative'
        else:
            sentiment_class = 'neutral'

        title = news.get('title', '')[:60]
        source = news.get('source', '')

        html += f"""
                <div class="news-item">
                    <div class="news-sentiment {sentiment_class}"></div>
                    <div class="news-content">
                        <div class="news-title">{title}</div>
                        <div class="news-meta">
                            <span class="news-source">{source}</span>
                        </div>
                    </div>
                </div>
"""

    html += """
            </div>

            <div class="sidebar">
                <div class="sidebar-card">
                    <h3>📊 来源分布</h3>
"""

    # 添加来源分布
    for src, count in sorted(sources.items(), key=lambda x: -x[1])[:8]:
        html += f"""
                    <div class="source-item">
                        <span>{src}</span>
                        <span>{count}</span>
                    </div>
"""

    html += """
                </div>

                <div class="sidebar-card">
                    <h3>🔥 热点话题</h3>
"""

    # 添加热点话题
    if hot_topics:
        for topic in hot_topics[:8]:
            html += f"""
                    <div class="hot-item">
                        <span class="hot-keyword">{topic['keyword']}</span>
                        <span class="hot-count"> ({topic['count']}次)</span>
                    </div>
"""

    html += f"""
                </div>
            </div>
        </div>

        <div class="footer">
            <p>NewsHub v3.0 | 自动新闻聚合与智能分析</p>
        </div>
    </div>
</body>
</html>
"""

    return html

def save_dashboard(news_list: list) -> str:
    """生成并保存仪表盘"""
    # 检测热点
    try:
        from hot_topics import detect_hot_topics
        hot_topics = detect_hot_topics(news_list)
    except:
        hot_topics = []

    html = generate_dashboard(news_list, hot_topics=hot_topics)

    with open(DASHBOARD_FILE, 'w', encoding='utf-8') as f:
        f.write(html)

    return str(DASHBOARD_FILE)

# 命令行入口
if __name__ == "__main__":
    from news_fetcher import fetch_all

    print("  ▶ 生成仪表盘...")
    news = fetch_all(quiet=True)
    path = save_dashboard(news)
    print(f"  ✓ 仪表盘已生成: {path}")

