#!/usr/bin/env python3
"""NewsHub 高级搜索和过滤 v1.0"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import re
from datetime import datetime, timedelta
from pathlib import Path
import json

CACHE_FILE = Path(__file__).parent / '.news_cache.json'

def load_news() -> list:
    """加载缓存的新闻"""
    if not CACHE_FILE.exists():
        return []

    with open(CACHE_FILE, 'r', encoding='utf-8') as f:
        data = json.load(f)
        return data.get('news', [])

def search_news(query: str, news_list: list = None) -> list:
    """搜索新闻"""
    if news_list is None:
        news_list = load_news()

    query = query.lower()
    results = []

    for news in news_list:
        title = news.get('title', '').lower()
        source = news.get('source', '').lower()

        if query in title or query in source:
            results.append(news)

    return results

def filter_by_keywords(news_list: list, keywords: list, mode: str = 'any') -> list:
    """按关键词过滤"""
    results = []

    for news in news_list:
        title = news.get('title', '').lower()

        if mode == 'any':
            # 包含任意关键词
            if any(kw.lower() in title for kw in keywords):
                results.append(news)
        elif mode == 'all':
            # 包含所有关键词
            if all(kw.lower() in title for kw in keywords):
                results.append(news)
        elif mode == 'none':
            # 不包含任何关键词
            if not any(kw.lower() in title for kw in keywords):
                results.append(news)

    return results

def filter_by_source(news_list: list, sources: list) -> list:
    """按来源过滤"""
    sources_lower = [s.lower() for s in sources]
    return [
        n for n in news_list
        if n.get('source', '').lower() in sources_lower
    ]

def filter_by_sentiment(news_list: list, sentiment: str) -> list:
    """按情感过滤"""
    results = []

    for news in news_list:
        score = news.get('score', 0)

        if sentiment == 'positive' and score > 20:
            results.append(news)
        elif sentiment == 'negative' and score < -20:
            results.append(news)
        elif sentiment == 'neutral' and -20 <= score <= 20:
            results.append(news)

    return results

def filter_by_time(news_list: list, hours: int) -> list:
    """按时间过滤"""
    cutoff = datetime.now() - timedelta(hours=hours)
    results = []

    for news in news_list:
        time_str = news.get('time', '')
        try:
            news_time = datetime.fromisoformat(time_str)
            if news_time > cutoff:
                results.append(news)
        except:
            pass

    return results

def search_regex(news_list: list, pattern: str) -> list:
    """正则搜索"""
    try:
        regex = re.compile(pattern, re.IGNORECASE)
        return [
            n for n in news_list
            if regex.search(n.get('title', ''))
        ]
    except re.error:
        return []

def advanced_search(
    news_list: list,
    query: str = None,
    keywords: list = None,
    sources: list = None,
    sentiment: str = None,
    hours: int = None,
    regex: str = None
) -> list:
    """高级搜索"""
    results = news_list

    if query:
        results = search_news(query, results)

    if keywords:
        results = filter_by_keywords(results, keywords)

    if sources:
        results = filter_by_source(results, sources)

    if sentiment:
        results = filter_by_sentiment(results, sentiment)

    if hours:
        results = filter_by_time(results, hours)

    if regex:
        results = search_regex(results, regex)

    return results

def print_results(news_list: list, limit: int = 20):
    """打印搜索结果"""
    if not news_list:
        print("\n  未找到匹配的新闻")
        return

    print(f"\n  找到 {len(news_list)} 条新闻:\n")

    for i, news in enumerate(news_list[:limit], 1):
        title = news.get('title', '')[:50]
        source = news.get('source', '')
        score = news.get('score', 0)

        if score > 20:
            emoji = '🟢'
        elif score < -20:
            emoji = '🔴'
        else:
            emoji = '⚪'

        print(f"  {i}. {emoji} [{source}] {title}")

# 预设关键词组
KEYWORD_GROUPS = {
    '科技': ['AI', 'GPT', '芯片', '半导体', '科技', '互联网', '软件', '硬件'],
    '金融': ['股票', '基金', '投资', '银行', '金融', '利率', '央行'],
    '加密': ['比特币', 'BTC', 'ETH', '加密', '区块链', 'Web3', 'NFT'],
    '能源': ['原油', '石油', '天然气', '能源', '新能源', '光伏', '风电'],
    '地产': ['房地产', '房价', '地产', '住房', '商业地产'],
    '医疗': ['医疗', '医药', '医院', '健康', '生物', '制药'],
    '汽车': ['汽车', '新能源车', '特斯拉', '电动车', '自动驾驶'],
}

def get_news_by_group(group_name: str, news_list: list = None) -> list:
    """按预设组获取新闻"""
    if news_list is None:
        news_list = load_news()

    keywords = KEYWORD_GROUPS.get(group_name, [])
    if not keywords:
        return []

    return filter_by_keywords(news_list, keywords)

# 命令行入口
if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description='新闻搜索和过滤')
    parser.add_argument('query', nargs='?', help='搜索关键词')
    parser.add_argument('--source', '-s', help='来源过滤')
    parser.add_argument('--sentiment', choices=['positive', 'negative', 'neutral'], help='情感过滤')
    parser.add_argument('--hours', type=int, help='时间过滤（小时）')
    parser.add_argument('--regex', help='正则搜索')
    parser.add_argument('--group', help='预设组（科技/金融/加密/能源/地产/医疗/汽车）')
    parser.add_argument('--limit', type=int, default=20, help='显示数量')

    args = parser.parse_args()

    news = load_news()

    if args.group:
        results = get_news_by_group(args.group, news)
        print(f"\n  📰 {args.group}相关新闻")
    elif args.query:
        results = advanced_search(
            news,
            query=args.query,
            sources=[args.source] if args.source else None,
            sentiment=args.sentiment,
            hours=args.hours,
            regex=args.regex
        )
    else:
        print("  用法: python search.py <关键词> [--source 来源] [--sentiment 情感] [--hours 小时]")
        print("\n  预设组:")
        for group in KEYWORD_GROUPS:
            print(f"    --group {group}")
        exit(0)

    print_results(results, args.limit)

