#!/usr/bin/env python3
"""NewsHub Telegram 推送 v1.0"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import json
import urllib.request
import ssl
from pathlib import Path

# 配置文件
CONFIG_FILE = Path(__file__).parent / 'telegram_config.json'

def load_config() -> dict:
    """加载配置"""
    try:
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {}

def save_config(config: dict):
    """保存配置"""
    with open(CONFIG_FILE, 'w', encoding='utf-8') as f:
        json.dump(config, f, ensure_ascii=False, indent=2)

def send_message(bot_token: str, chat_id: str, text: str, parse_mode: str = 'HTML') -> bool:
    """发送消息"""
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        url = f"https://api.telegram.org/bot{bot_token}/sendMessage"

        data = {
            "chat_id": chat_id,
            "text": text,
            "parse_mode": parse_mode,
            "disable_web_page_preview": True
        }

        req = urllib.request.Request(
            url,
            data=json.dumps(data).encode('utf-8'),
            headers={"Content-Type": "application/json"}
        )

        with urllib.request.urlopen(req, timeout=15, context=ctx) as resp:
            result = json.loads(resp.read().decode('utf-8'))
            return result.get('ok', False)
    except Exception as e:
        print(f"发送失败: {e}")
        return False

def format_news_html(news_list: list, title: str = "📰 新闻速递") -> str:
    """格式化新闻为 HTML"""
    lines = [f"<b>{title}</b>", ""]

    for i, news in enumerate(news_list[:10], 1):
        n_title = news.get('title', '')[:80]
        source = news.get('source', '')
        url = news.get('url', '')
        score = news.get('score', 0)

        # 情感标记
        if score > 20:
            emoji = "🟢"
        elif score < -20:
            emoji = "🔴"
        else:
            emoji = "⚪"

        if url:
            lines.append(f"{i}. {emoji} <a href=\"{url}\">{n_title}</a>")
        else:
            lines.append(f"{i}. {emoji} {n_title}")
        lines.append(f"   <i>{source}</i>")
        lines.append("")

    lines.append("---")
    lines.append("<i>NewsHub 自动推送</i>")

    return "\n".join(lines)

def format_digest_html(news_list: list) -> str:
    """格式化摘要"""
    lines = ["<b>📰 今日摘要</b>", ""]

    # 按来源分组
    sources = {}
    for news in news_list[:20]:
        src = news.get('source', 'unknown')
        if src not in sources:
            sources[src] = []
        sources[src].append(news)

    for source, news_items in sources.items():
        lines.append(f"<b>{source}</b>")
        for news in news_items[:3]:
            title = news.get('title', '')[:50]
            lines.append(f"• {title}")
        lines.append("")

    return "\n".join(lines)

def push_news(news_list: list, bot_token: str = None, chat_id: str = None) -> bool:
    """推送新闻"""
    config = load_config()

    bot_token = bot_token or config.get('bot_token')
    chat_id = chat_id or config.get('chat_id')

    if not bot_token or not chat_id:
        print("未配置 Telegram Bot")
        return False

    html = format_news_html(news_list)
    return send_message(bot_token, chat_id, html)

def push_digest(news_list: list, bot_token: str = None, chat_id: str = None) -> bool:
    """推送摘要"""
    config = load_config()

    bot_token = bot_token or config.get('bot_token')
    chat_id = chat_id or config.get('chat_id')

    if not bot_token or not chat_id:
        return False

    html = format_digest_html(news_list)
    return send_message(bot_token, chat_id, html)

def push_alert(title: str, content: str, bot_token: str = None, chat_id: str = None) -> bool:
    """推送告警"""
    config = load_config()

    bot_token = bot_token or config.get('bot_token')
    chat_id = chat_id or config.get('chat_id')

    if not bot_token or not chat_id:
        return False

    html = f"<b>⚠️ {title}</b>\n\n{content}"
    return send_message(bot_token, chat_id, html)

def setup_bot():
    """配置 Bot"""
    print("\n  📱 Telegram Bot 配置")
    print("  " + "─" * 40)
    print("\n  步骤:")
    print("  1. 在 Telegram 中找到 @BotFather")
    print("  2. 发送 /newbot 创建新 Bot")
    print("  3. 获取 Bot Token")
    print("  4. 创建群组或频道，添加 Bot")
    print("  5. 获取 Chat ID (可用 @userinfobot)")

    bot_token = input("\n  Bot Token: ").strip()
    chat_id = input("  Chat ID: ").strip()

    if bot_token and chat_id:
        config = {
            'bot_token': bot_token,
            'chat_id': chat_id
        }
        save_config(config)

        # 测试
        print("\n  测试发送...")
        if send_message(bot_token, chat_id, "✅ NewsHub 配置成功！"):
            print("  ✓ 配置成功")
        else:
            print("  ✗ 发送失败，请检查配置")
    else:
        print("  ✗ 配置取消")

# 命令行入口
if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description='Telegram 推送')
    parser.add_argument('action', choices=['test', 'push', 'digest', 'alert', 'setup'])
    parser.add_argument('--title', default='告警', help='告警标题')
    parser.add_argument('--content', default='', help='告警内容')

    args = parser.parse_args()

    if args.action == 'setup':
        setup_bot()

    elif args.action == 'test':
        config = load_config()
        success = push_alert("测试消息", "这是一条测试消息")
        print("✅ 测试成功" if success else "❌ 测试失败")

    elif args.action == 'push':
        from news_fetcher import fetch_all
        news = fetch_all(quiet=True)
        success = push_news(news[:10])
        print("✅ 推送成功" if success else "❌ 推送失败")

    elif args.action == 'digest':
        from news_fetcher import fetch_all
        news = fetch_all(quiet=True)
        success = push_digest(news)
        print("✅ 摘要发送成功" if success else "❌ 发送失败")

    elif args.action == 'alert':
        push_alert(args.title, args.content)

