#!/usr/bin/env python3
"""NewsHub 配置管理 v1.0"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import json
from pathlib import Path

CONFIG_DIR = Path(__file__).parent

# 默认配置
DEFAULT_CONFIGS = {
    'feishu_config.json': {
        'webhook_url': '',
        'keywords': ['AI', '科技', '金融']
    },
    'telegram_config.json': {
        'bot_token': '',
        'chat_id': ''
    },
    'wechat_config.json': {
        'webhook_url': ''
    },
    'qq_config.json': {
        'host': '127.0.0.1',
        'port': 5700
    },
    'schedule.json': {
        'tasks': []
    }
}

def list_configs():
    """列出所有配置"""
    print("\n  ⚙️ 配置文件列表")
    print("  " + "─" * 50)

    for config_file, default in DEFAULT_CONFIGS.items():
        path = CONFIG_DIR / config_file
        status = "✅ 已配置" if path.exists() else "❌ 未配置"
        print(f"\n  {status} {config_file}")

        if path.exists():
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    config = json.load(f)

                # 显示配置项（隐藏敏感信息）
                for key, value in config.items():
                    if 'token' in key.lower() or 'secret' in key.lower() or 'key' in key.lower():
                        display = '***' if value else '(空)'
                    elif 'url' in key.lower():
                        display = value[:30] + '...' if len(str(value)) > 30 else value
                    else:
                        display = value

                    print(f"    {key}: {display}")
            except Exception as e:
                print(f"    ⚠️ 读取失败: {e}")

def init_configs():
    """初始化所有配置文件"""
    print("\n  🔧 初始化配置文件")
    print("  " + "─" * 50)

    for config_file, default in DEFAULT_CONFIGS.items():
        path = CONFIG_DIR / config_file

        if path.exists():
            print(f"  ⏭️ {config_file} 已存在，跳过")
        else:
            with open(path, 'w', encoding='utf-8') as f:
                json.dump(default, f, ensure_ascii=False, indent=2)
            print(f"  ✅ 创建 {config_file}")

def show_config(name: str):
    """显示指定配置"""
    config_file = f"{name}_config.json"
    path = CONFIG_DIR / config_file

    if not path.exists():
        print(f"  ❌ 配置文件不存在: {config_file}")
        return

    with open(path, 'r', encoding='utf-8') as f:
        config = json.load(f)

    print(f"\n  📄 {config_file}")
    print("  " + "─" * 40)
    print(json.dumps(config, ensure_ascii=False, indent=2))

def set_config(name: str, key: str, value: str):
    """设置配置项"""
    config_file = f"{name}_config.json"
    path = CONFIG_DIR / config_file

    # 加载现有配置或默认配置
    if path.exists():
        with open(path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    else:
        config = DEFAULT_CONFIGS.get(config_file, {})

    # 更新配置
    config[key] = value

    # 保存
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(config, f, ensure_ascii=False, indent=2)

    print(f"  ✅ 已更新 {name}.{key}")

def validate_configs():
    """验证配置"""
    print("\n  🔍 验证配置")
    print("  " + "─" * 50)

    issues = []

    # 检查飞书
    feishu_path = CONFIG_DIR / 'feishu_config.json'
    if feishu_path.exists():
        with open(feishu_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        if not config.get('webhook_url'):
            issues.append("飞书 webhook_url 未配置")
    else:
        issues.append("飞书配置文件不存在")

    # 检查 Telegram
    telegram_path = CONFIG_DIR / 'telegram_config.json'
    if telegram_path.exists():
        with open(telegram_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        if not config.get('bot_token') or not config.get('chat_id'):
            issues.append("Telegram bot_token 或 chat_id 未配置")

    # 检查微信
    wechat_path = CONFIG_DIR / 'wechat_config.json'
    if wechat_path.exists():
        with open(wechat_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        if not config.get('webhook_url'):
            issues.append("微信 webhook_url 未配置")

    if issues:
        print("\n  ⚠️ 发现以下问题:")
        for issue in issues:
            print(f"    - {issue}")

        print("\n  💡 使用以下命令配置:")
        print("    python news_hub.py config set feishu webhook_url <url>")
        print("    python news_hub.py telegram setup")
    else:
        print("\n  ✅ 所有推送渠道配置正常")

