#!/usr/bin/env python3
"""NewsHub 飞书推送增强 v3.0"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent))
from news_fetcher import fetch_all
from datetime import datetime
import json, ssl, time, urllib.request

BASE_DIR = Path(r"D:\OpenClaw\workspace\30-scripts-tools")
CONFIG_FILE = BASE_DIR / "feishu-tools" / "feishu-config.json"
HISTORY_FILE = BASE_DIR / "news_history.json"
LOG_FILE = Path(__file__).parent / "send_log.json"
TEMPLATE_FILE = Path(__file__).parent / 'feishu_templates.json'

# ========== 样式 ==========
class S:
    HEADER, BLUE, CYAN, GREEN, YELLOW, RED, BOLD, END = "\033[95m", "\033[94m", "\033[96m", "\033[92m", "\033[93m", "\033[91m", "\033[1m", "\033[0m"

def c(s, t): return f"{s}{t}{S.END}" if sys.stdout.isatty() else t
def B(t): return c(S.BOLD, t)
def G(t): return c(S.GREEN, t)
def Y(t): return c(S.YELLOW, t)
def L(t): return c(S.BLUE, t)
def C(t): return c(S.CYAN, t)
def R(t): return c(S.RED, t)

def info(m): print(f"  {L('▶')} {m}")
def ok(m): print(f"  {G('✓')} {G(m)}")
def warn(m): print(f"  {Y('⚠')} {Y(m)}")
def error(m): print(f"  {R('✗')} {R(m)}")

def banner(t, i="📡"):
    print()
    print(C("╔" + "═" * 48 + "╗"))
    print(C("║") + f"  {i} {B(t)}".ljust(48) + C("║"))
    print(C("╚" + "═" * 48 + "╝"))
    print()

# ========== 配置 ==========
def load_feishu_config():
    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {}

def load_history():
    if HISTORY_FILE.exists():
        with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data if isinstance(data, list) else data.get('sent', [])
    return []

def save_history(hist):
    with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
        json.dump(hist[-2000:], f, ensure_ascii=False)

def load_log():
    if LOG_FILE.exists():
        with open(LOG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return []

def save_log(logs):
    with open(LOG_FILE, 'w', encoding='utf-8') as f:
        json.dump(logs[-200:], f, ensure_ascii=False)

def add_log(mode, sent, total, group=None):
    logs = load_log()
    logs.append({
        "time": datetime.now().isoformat(),
        "mode": mode,
        "sent": sent,
        "total": total,
        "group": group
    })
    save_log(logs)

# ========== 模板管理 ==========
def load_templates():
    """加载卡片模板"""
    if TEMPLATE_FILE.exists():
        with open(TEMPLATE_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {}

def save_templates(templates):
    """保存卡片模板"""
    with open(TEMPLATE_FILE, 'w', encoding='utf-8') as f:
        json.dump(templates, f, ensure_ascii=False, indent=2)

DEFAULT_TEMPLATES = {
    "digest": {
        "name": "摘要卡片",
        "header_color": "green",
        "show_source": True,
        "show_sentiment": True,
        "max_items": 6
    },
    "alert": {
        "name": "告警卡片",
        "header_color": "red",
        "show_source": True,
        "show_sentiment": True,
        "max_items": 5
    },
    "brief": {
        "name": "简报卡片",
        "header_color": "blue",
        "show_source": False,
        "show_sentiment": False,
        "max_items": 10
    },
    "rich": {
        "name": "富文本卡片",
        "header_color": "purple",
        "show_source": True,
        "show_sentiment": True,
        "max_items": 8,
        "show_chart": True
    }
}

def init_templates():
    """初始化模板"""
    templates = load_templates()
    for name, template in DEFAULT_TEMPLATES.items():
        if name not in templates:
            templates[name] = template
    save_templates(templates)
    return templates

# ========== API ==========
def get_access_token():
    cfg = load_feishu_config()
    url = "https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal"
    data = json.dumps({"app_id": cfg['app_id'], "app_secret": cfg['app_secret']}).encode()
    req = urllib.request.Request(url, data=data, headers={'Content-Type': 'application/json'}, method='POST')
    ctx = ssl.create_default_context()
    with urllib.request.urlopen(req, timeout=10, context=ctx) as r:
        return json.loads(r.read()).get('tenant_access_token', '')

def send_card(token, receive_id, card, receive_id_type='open_id'):
    """发送卡片消息"""
    url = f"https://open.feishu.cn/open-apis/im/v1/messages?receive_id_type={receive_id_type}"
    payload = json.dumps({
        "receive_id": receive_id,
        "msg_type": "interactive",
        "content": json.dumps(card)
    }).encode('utf-8')
    req = urllib.request.Request(
        url, data=payload,
        headers={
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {token}'
        },
        method='POST'
    )
    ctx = ssl.create_default_context()
    for _ in range(3):
        try:
            with urllib.request.urlopen(req, timeout=30, context=ctx) as r:
                return json.loads(r.read())
        except Exception as e:
            time.sleep(0.5)
    return {"code": -1, "msg": str(e)}

def send_text(token, receive_id, text, receive_id_type='open_id'):
    """发送文本消息"""
    url = f"https://open.feishu.cn/open-apis/im/v1/messages?receive_id_type={receive_id_type}"
    payload = json.dumps({
        "receive_id": receive_id,
        "msg_type": "text",
        "content": json.dumps({"text": text})
    }).encode('utf-8')
    req = urllib.request.Request(
        url, data=payload,
        headers={
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {token}'
        },
        method='POST'
    )
    ctx = ssl.create_default_context()
    try:
        with urllib.request.urlopen(req, timeout=30, context=ctx) as r:
            return json.loads(r.read())
    except:
        return {"code": -1}

def send_batch(token, receive_ids, card, interval=0.3):
    """批量发送卡片"""
    results = []
    for rid in receive_ids:
        result = send_card(token, rid, card)
        results.append((rid, result.get('code') == 0))
        time.sleep(interval)
    return results

# ========== 卡片构建 ==========
def build_digest_card(news_list, template=None):
    """构建摘要卡片"""
    tmpl = template or DEFAULT_TEMPLATES['digest']
    items = []

    for i, n in enumerate(news_list[:tmpl.get('max_items', 6)], 1):
        title = n['title'][:35] + "..." if len(n['title']) > 35 else n['title']
        source = n.get('source', '')

        # 情感标签
        if tmpl.get('show_sentiment', True):
            score = n.get('score', 0)
            sent_icon = "🟢" if score > 20 else ("🔴" if score < -20 else "⚪")
        else:
            sent_icon = ""

        # 来源
        if tmpl.get('show_source', True):
            src_icon = "🔹" if "新浪" in source else ("🔸" if "Investing" in source else "🔶")
            src_text = f"\n> {src_icon} {source}"
        else:
            src_text = ""

        items.append({
            "tag": "markdown",
            "content": f"**{i}.** {sent_icon} {title}{src_text}"
        })

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"📊 财经速报 {datetime.now().strftime('%H:%M')}"},
            "template": tmpl.get('header_color', 'green')
        },
        "elements": [
            *items,
            {"tag": "hr"},
            {"tag": "div", "text": {"tag": "lark_md", "content": f"📱 NewsHub · {len(news_list)}条"}}
        ]
    }

def build_alert_card(news_list, keywords=None):
    """构建告警卡片"""
    items = []

    for n in news_list[:5]:
        title = n['title'][:40] + "..." if len(n['title']) > 40 else n['title']
        source = n.get('source', '')
        url = n.get('url', '')

        # 高亮关键词
        highlight = ""
        if keywords:
            for kw in keywords:
                if kw in title:
                    highlight = f"🔔 命中: `{kw}`\n\n"
                    break

        items.append({
            "tag": "markdown",
            "content": f"{highlight}**{title}**\n> {source}"
        })
        items.append({"tag": "hr"})

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"⚠️ 重要告警 {datetime.now().strftime('%H:%M')}"},
            "template": "red"
        },
        "elements": items[:-1] if items else []
    }

def build_rich_card(news_list):
    """构建富文本卡片 - 带统计图表"""
    # 分类统计
    categories = {}
    sentiments = {'positive': 0, 'negative': 0, 'neutral': 0}

    for n in news_list:
        cat = n.get('category', 'other')
        categories[cat] = categories.get(cat, 0) + 1

        score = n.get('score', 0)
        if score > 20:
            sentiments['positive'] += 1
        elif score < -20:
            sentiments['negative'] += 1
        else:
            sentiments['neutral'] += 1

    # 分类条
    cat_names = {
        'stock': '📈 股市', 'forex': '💱 外汇', 'crypto': '₿ 加密',
        'tech': '💻 科技', 'energy': '⚡ 能源', 'commodity': '🛢️ 商品'
    }
    cat_bars = []
    for cat, cnt in sorted(categories.items(), key=lambda x: -x[1])[:5]:
        name = cat_names.get(cat, cat)
        bar = "█" * min(cnt, 10)
        cat_bars.append(f"{name}: {bar} {cnt}")

    # 新闻列表
    items = []
    for i, n in enumerate(news_list[:6], 1):
        title = n['title'][:30] + "..." if len(n['title']) > 30 else n['title']
        score = n.get('score', 0)
        icon = "🟢" if score > 20 else ("🔴" if score < -20 else "⚪")
        items.append(f"{i}. {icon} {title}")

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"📊 深度分析 {datetime.now().strftime('%H:%M')}"},
            "template": "purple"
        },
        "elements": [
            {"tag": "markdown", "content": f"**📰 总数:** {len(news_list)}"},
            {"tag": "markdown", "content": f"**🟢 利好:** {sentiments['positive']} | **🔴 利空:** {sentiments['negative']} | **⚪ 中性:** {sentiments['neutral']}"},
            {"tag": "hr"},
            {"tag": "markdown", "content": "**📊 分类分布**\n" + "\n".join(cat_bars)},
            {"tag": "hr"},
            {"tag": "markdown", "content": "**📰 热门新闻**\n" + "\n".join(items)},
            {"tag": "hr"},
            {"tag": "div", "text": {"tag": "lark_md", "content": "🤖 NewsHub 深度分析"}}
        ]
    }

def build_hourly_card(news_list):
    """构建整点简报卡片"""
    now = datetime.now()
    hour = now.hour

    # 最近一小时新闻
    items = []
    for i, n in enumerate(news_list[:5], 1):
        title = n['title'][:35] + "..." if len(n['title']) > 35 else n['title']
        items.append(f"**{i}.** {title}")

    return {
        "header": {
            "title": {"tag": "plain_text", "content": f"⏰ {hour}:00 整点简报"},
            "template": "blue"
        },
        "elements": [
            {"tag": "markdown", "content": "\n\n".join(items)},
            {"tag": "hr"},
            {"tag": "div", "text": {"tag": "lark_md", "content": f"📱 {len(news_list)}条新闻 · NewsHub"}}
        ]
    }

def build_weekly_card(news_list, week_num):
    """构建周报卡片"""
    # 分类统计
    categories = {}
    for n in news_list:
        cat = n.get('category', 'other')
        categories[cat] = categories.get(cat, 0) + 1

    # 情感统计
    pos = sum(1 for n in news_list if n.get('score', 0) > 20)
    neg = sum(1 for n in news_list if n.get('score', 0) < -20)

    # 热门关键词
