#!/usr/bin/env python3
"""NewsHub Discord 推送 v1.0"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import json
import urllib.request
import ssl
from pathlib import Path
from datetime import datetime

CONFIG_FILE = Path(__file__).parent / 'discord_config.json'

def load_config() -> dict:
    """加载配置"""
    try:
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {}

def save_config(config: dict):
    """保存配置"""
    with open(CONFIG_FILE, 'w', encoding='utf-8') as f:
        json.dump(config, f, ensure_ascii=False, indent=2)

def send_webhook(webhook_url: str, content: str) -> bool:
    """发送 Discord Webhook"""
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        data = {"content": content}

        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(data).encode('utf-8'),
            headers={"Content-Type": "application/json"}
        )

        with urllib.request.urlopen(req, timeout=15, context=ctx) as resp:
            return resp.status == 204
    except Exception as e:
        print(f"发送失败: {e}")
        return False

def send_embed(webhook_url: str, title: str, description: str, 
               color: int = 0x3498db, fields: list = None) -> bool:
    """发送 Embed 消息"""
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        embed = {
            "title": title,
            "description": description,
            "color": color,
            "timestamp": datetime.utcnow().isoformat(),
            "footer": {"text": "NewsHub"}
        }

        if fields:
            embed["fields"] = fields

        data = {"embeds": [embed]}

        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(data).encode('utf-8'),
            headers={"Content-Type": "application/json"}
        )

        with urllib.request.urlopen(req, timeout=15, context=ctx) as resp:
            return resp.status == 204
    except Exception as e:
        print(f"发送失败: {e}")
        return False

def format_news_embed(news_list: list, title: str = "📰 新闻速递") -> dict:
    """格式化为 Discord Embed"""
    fields = []

    for i, news in enumerate(news_list[:10], 1):
        n_title = news.get('title', '')[:100]
        source = news.get('source', '')
        url = news.get('url', '')
        score = news.get('score', 0)

        # 情感
        if score > 20:
            emoji = "🟢"
        elif score < -20:
            emoji = "🔴"
        else:
            emoji = "⚪"

        # 字段
        field = {
            "name": f"{i}. {emoji} {n_title[:50]}",
            "value": f"[{source}]({url})" if url else source,
            "inline": False
        }
        fields.append(field)

    return {
        "title": title,
        "description": f"共 {len(news_list)} 条新闻",
        "color": 0x3498db,
        "fields": fields[:25],  # Discord 限制 25 个字段
        "timestamp": datetime.utcnow().isoformat(),
        "footer": {"text": "NewsHub 自动推送"}
    }

def push_news(news_list: list, webhook_url: str = None) -> bool:
    """推送新闻"""
    config = load_config()
    webhook_url = webhook_url or config.get('webhook_url')

    if not webhook_url:
        print("未配置 Discord Webhook")
        return False

    embed = format_news_embed(news_list)

    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        data = {"embeds": [embed]}

        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(data).encode('utf-8'),
            headers={"Content-Type": "application/json"}
        )

        with urllib.request.urlopen(req, timeout=15, context=ctx) as resp:
            return resp.status == 204
    except Exception as e:
        print(f"发送失败: {e}")
        return False

def push_alert(title: str, content: str, webhook_url: str = None) -> bool:
    """推送告警"""
    config = load_config()
    webhook_url = webhook_url or config.get('webhook_url')

    if not webhook_url:
        return False

    return send_embed(webhook_url, f"⚠️ {title}", content, color=0xe74c3c)

def push_digest(news_list: list, webhook_url: str = None) -> bool:
    """推送摘要"""
    config = load_config()
    webhook_url = webhook_url or config.get('webhook_url')

    if not webhook_url:
        return False

    # 分类统计
    positive = sum(1 for n in news_list if n.get('score', 0) > 20)
    negative = sum(1 for n in news_list if n.get('score', 0) < -20)
    neutral = len(news_list) - positive - negative

    fields = [
        {"name": "📈 利好", "value": str(positive), "inline": True},
        {"name": "📉 利空", "value": str(negative), "inline": True},
        {"name": "⚪ 中性", "value": str(neutral), "inline": True},
    ]

    return send_embed(
        webhook_url, 
        "📊 今日摘要", 
        f"共 {len(news_list)} 条新闻",
        color=0x2ecc71,
        fields=fields
    )

def setup():
    """配置 Discord Webhook"""
    print("\n  📱 Discord Webhook 配置")
    print("  " + "─" * 40)
    print("\n  步骤:")
    print("  1. 打开 Discord 服务器设置")
    print("  2. 进入 整合 > Webhooks")
    print("  3. 点击 '新建 Webhook'")
    print("  4. 复制 Webhook URL")

    webhook_url = input("\n  Webhook URL: ").strip()

    if webhook_url:
        config = {'webhook_url': webhook_url}
        save_config(config)

        print("\n  测试发送...")
        if send_webhook(webhook_url, "✅ NewsHub 配置成功！"):
            print("  ✓ 配置成功")
        else:
            print("  ✗ 发送失败，请检查 URL")
    else:
        print("  ✗ 配置取消")

# 命令行入口
if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description='Discord 推送')
    parser.add_argument('action', choices=['test', 'push', 'digest', 'alert', 'setup'])
    parser.add_argument('--title', default='告警', help='告警标题')
    parser.add_argument('--content', default='', help='告警内容')

    args = parser.parse_args()

    if args.action == 'setup':
        setup()

    elif args.action == 'test':
        config = load_config()
        success = push_alert("测试消息", "这是一条测试消息")
        print("✅ 测试成功" if success else "❌ 测试失败")

    elif args.action == 'push':
        from news_fetcher import fetch_all
        news = fetch_all(quiet=True)
        success = push_news(news[:10])
        print("✅ 推送成功" if success else "❌ 推送失败")

    elif args.action == 'digest':
        from news_fetcher import fetch_all
        news = fetch_all(quiet=True)
        success = push_digest(news)
        print("✅ 摘要发送成功" if success else "❌ 发送失败")

    elif args.action == 'alert':
        push_alert(args.title, args.content)

