#!/usr/bin/env python3
"""NewsHub Slack 推送 v1.0"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import json
import urllib.request
import ssl
from pathlib import Path
from datetime import datetime

CONFIG_FILE = Path(__file__).parent / 'slack_config.json'

def load_config() -> dict:
    """加载配置"""
    try:
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {}

def save_config(config: dict):
    """保存配置"""
    with open(CONFIG_FILE, 'w', encoding='utf-8') as f:
        json.dump(config, f, ensure_ascii=False, indent=2)

def send_message(webhook_url: str, text: str, blocks: list = None) -> bool:
    """发送 Slack 消息"""
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        data = {"text": text}
        if blocks:
            data["blocks"] = blocks

        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(data).encode('utf-8'),
            headers={"Content-Type": "application/json"}
        )

        with urllib.request.urlopen(req, timeout=15, context=ctx) as resp:
            return resp.status == 200
    except Exception as e:
        print(f"发送失败: {e}")
        return False

def build_news_blocks(news_list: list, title: str = "📰 新闻速递") -> list:
    """构建 Slack Block Kit 消息"""
    blocks = [
        {
            "type": "header",
            "text": {
                "type": "plain_text",
                "text": title
            }
        },
        {
            "type": "context",
            "elements": [
                {
                    "type": "mrkdwn",
                    "text": f"📅 {datetime.now().strftime('%Y-%m-%d %H:%M')} | 共 {len(news_list)} 条新闻"
                }
            ]
        },
        {"type": "divider"}
    ]

    for i, news in enumerate(news_list[:10], 1):
        title = news.get('title', '')[:80]
        source = news.get('source', '')
        url = news.get('url', '')
        score = news.get('score', 0)

        # 情感标记
        if score > 20:
            emoji = "large_green_circle"
            sentiment = "利好"
        elif score < -20:
            emoji = "red_circle"
            sentiment = "利空"
        else:
            emoji = "white_circle"
            sentiment = "中性"

        block = {
            "type": "section",
            "text": {
                "type": "mrkdwn",
                "text": f":{emoji}: *{i}. {title}*"
            },
            "accessory": {
                "type": "button",
                "text": {"type": "plain_text", "text": source[:10]},
                "url": url if url else "https://example.com",
                "action_id": f"button-{i}"
            } if url else None
        }

        if not url:
            block["text"]["text"] += f"\n_来源: {source}_"
            del block["accessory"]

        blocks.append(block)

    blocks.append({"type": "divider"})
    blocks.append({
        "type": "context",
        "elements": [
            {"type": "mrkdwn", "text": "🤖 NewsHub 自动推送"}
        ]
    })

    return blocks

def push_news(news_list: list, webhook_url: str = None) -> bool:
    """推送新闻"""
    config = load_config()
    webhook_url = webhook_url or config.get('webhook_url')

    if not webhook_url:
        print("未配置 Slack Webhook")
        return False

    blocks = build_news_blocks(news_list)
    return send_message(webhook_url, "新闻速递", blocks)

def push_alert(title: str, content: str, webhook_url: str = None) -> bool:
    """推送告警"""
    config = load_config()
    webhook_url = webhook_url or config.get('webhook_url')

    if not webhook_url:
        return False

    blocks = [
        {
            "type": "header",
            "text": {"type": "plain_text", "text": f"⚠️ {title}"}
        },
        {
            "type": "section",
            "text": {"type": "mrkdwn", "text": content}
        },
        {"type": "divider"},
        {
            "type": "context",
            "elements": [{"type": "mrkdwn", "text": f"🕐 {datetime.now().strftime('%H:%M:%S')}"}]
        }
    ]

    return send_message(webhook_url, title, blocks)

def push_digest(news_list: list, webhook_url: str = None) -> bool:
    """推送摘要"""
    config = load_config()
    webhook_url = webhook_url or config.get('webhook_url')

    if not webhook_url:
        return False

    # 统计
    positive = sum(1 for n in news_list if n.get('score', 0) > 20)
    negative = sum(1 for n in news_list if n.get('score', 0) < -20)
    neutral = len(news_list) - positive - negative

    blocks = [
        {
            "type": "header",
            "text": {"type": "plain_text", "text": "📊 今日摘要"}
        },
        {
            "type": "section",
            "fields": [
                {"type": "mrkdwn", "text": f"*利好*\n:large_green_circle: {positive}"},
                {"type": "mrkdwn", "text": f"*利空*\n:red_circle: {negative}"},
                {"type": "mrkdwn", "text": f"*中性*\n:white_circle: {neutral}"},
                {"type": "mrkdwn", "text": f"*总计*\n📰 {len(news_list)}"}
            ]
        }
    ]

    return send_message(webhook_url, "今日摘要", blocks)

def setup():
    """配置 Slack Webhook"""
    print("\n  💬 Slack Webhook 配置")
    print("  " + "─" * 40)
    print("\n  步骤:")
    print("  1. 打开 Slack App 设置")
    print("  2. 创建 Incoming Webhook")
    print("  3. 选择推送频道")
    print("  4. 复制 Webhook URL")

    webhook_url = input("\n  Webhook URL: ").strip()

    if webhook_url:
        config = {'webhook_url': webhook_url}
        save_config(config)

        print("\n  测试发送...")
        if send_message(webhook_url, "✅ NewsHub 配置成功！"):
            print("  ✓ 配置成功")
        else:
            print("  ✗ 发送失败，请检查 URL")
    else:
        print("  ✗ 配置取消")

# 命令行入口
if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description='Slack 推送')
    parser.add_argument('action', choices=['test', 'push', 'digest', 'alert', 'setup'])
    parser.add_argument('--title', default='告警', help='告警标题')
    parser.add_argument('--content', default='', help='告警内容')

    args = parser.parse_args()

    if args.action == 'setup':
        setup()

    elif args.action == 'test':
        config = load_config()
        success = push_alert("测试消息", "这是一条测试消息")
        print("✅ 测试成功" if success else "❌ 测试失败")

    elif args.action == 'push':
        from news_fetcher import fetch_all
        news = fetch_all(quiet=True)
        success = push_news(news[:10])
        print("✅ 推送成功" if success else "❌ 推送失败")

    elif args.action == 'digest':
        from news_fetcher import fetch_all
        news = fetch_all(quiet=True)
        success = push_digest(news)
        print("✅ 摘要发送成功" if success else "❌ 发送失败")

    elif args.action == 'alert':
        push_alert(args.title, args.content)

