#!/usr/bin/env python3
"""NewsHub 通用 Webhook 推送 v1.0"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
import json
import urllib.request
import ssl
from pathlib import Path
from datetime import datetime

CONFIG_FILE = Path(__file__).parent / 'webhook_config.json'

def load_config() -> dict:
    """加载配置"""
    try:
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except:
        return {}

def save_config(config: dict):
    """保存配置"""
    with open(CONFIG_FILE, 'w', encoding='utf-8') as f:
        json.dump(config, f, ensure_ascii=False, indent=2)

def send_webhook(
    url: str,
    data: dict,
    headers: dict = None,
    method: str = 'POST'
) -> dict:
    """发送 Webhook 请求"""
    try:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

        req_headers = {"Content-Type": "application/json"}
        if headers:
            req_headers.update(headers)

        req = urllib.request.Request(
            url,
            data=json.dumps(data).encode('utf-8'),
            headers=req_headers,
            method=method
        )

        with urllib.request.urlopen(req, timeout=15, context=ctx) as resp:
            return {
                'success': True,
                'status': resp.status,
                'body': resp.read().decode('utf-8')
            }
    except Exception as e:
        return {
            'success': False,
            'error': str(e)
        }

def push_news(news_list: list, webhook_url: str = None, format_type: str = 'json') -> bool:
    """推送新闻到 Webhook"""
    config = load_config()
    webhook_url = webhook_url or config.get('webhook_url')

    if not webhook_url:
        print("未配置 Webhook URL")
        return False

    if format_type == 'json':
        data = {
            'timestamp': datetime.now().isoformat(),
            'count': len(news_list),
            'news': news_list[:20]
        }
    elif format_type == 'slack':
        # Slack 格式
        text_lines = [f"📰 新闻速递 ({len(news_list)}条)"]
        for i, n in enumerate(news_list[:10], 1):
            text_lines.append(f"{i}. {n.get('title', '')[:50]}")
        data = {'text': '\n'.join(text_lines)}
    elif format_type == 'discord':
