from typing import Dict, List, Optional, Any
from pathlib import Path
from threading import Lock
import hashlib

CACHE_FILE = Path(__file__).parent / '.news_cache.json'

# ========== 内存缓存 ==========
class MemoryCache:
    """内存缓存 (TTL 支持)"""

    def __init__(self, default_ttl: int = 300):
        self._cache: Dict[str, Dict] = {}
        self._lock = Lock()
        self.default_ttl = default_ttl

    def get(self, key: str) -> Optional[Any]:
        """获取缓存"""
        with self._lock:
            if key not in self._cache:
                return None

            item = self._cache[key]
            if item['expires_at'] and time.time() > item['expires_at']:
                del self._cache[key]
                return None

            return item['value']

    def set(self, key: str, value: Any, ttl: int = None):
        """设置缓存"""
        with self._lock:
            expires_at = time.time() + (ttl or self.default_ttl) if ttl != 0 else None
            self._cache[key] = {
                'value': value,
                'expires_at': expires_at,
                'created_at': time.time()
            }

    def delete(self, key: str):
        """删除缓存"""
        with self._lock:
            self._cache.pop(key, None)

    def clear(self):
        """清空缓存"""
        with self._lock:
            self._cache.clear()

    def cleanup(self):
        """清理过期缓存"""
        with self._lock:
            now = time.time()
            expired = [k for k, v in self._cache.items() 
                      if v['expires_at'] and now > v['expires_at']]
            for k in expired:
                del self._cache[k]

    def stats(self) -> Dict:
        """缓存统计"""
        with self._lock:
            total = len(self._cache)
            expired = sum(1 for v in self._cache.values() 
                         if v['expires_at'] and time.time() > v['expires_at'])
            size = sum(len(str(v['value'])) for v in self._cache.values())

            return {
                'total': total,
                'expired': expired,
                'active': total - expired,
                'size_bytes': size,
                'size_kb': round(size / 1024, 2)
            }

# ========== Redis 缓存 (可选) ==========
class RedisCache:
    """Redis 缓存 (需要 redis-py)"""

    def __init__(self, host: str = 'localhost', port: int = 6379, 
                 db: int = 0, prefix: str = 'newshub:'):
        self.prefix = prefix
        self._redis = None

        try:
            import redis
            self._redis = redis.Redis(host=host, port=port, db=db, decode_responses=True)
            self._redis.ping()
        except:
            pass

    @property
    def available(self) -> bool:
        return self._redis is not None

    def _key(self, key: str) -> str:
        return f"{self.prefix}{key}"

    def get(self, key: str) -> Optional[Any]:
        if not self._redis:
            return None
        try:
            value = self._redis.get(self._key(key))
            if value:
                return json.loads(value)
        except:
            pass
        return None

    def set(self, key: str, value: Any, ttl: int = 300):
        if not self._redis:
            return
        try:
            self._redis.setex(
                self._key(key),
                ttl,
                json.dumps(value, ensure_ascii=False)
            )
        except:
            pass

    def delete(self, key: str):
        if self._redis:
            self._redis.delete(self._key(key))

    def clear(self):
        if self._redis:
            keys = self._redis.keys(f"{self.prefix}*")
            if keys:
                self._redis.delete(*keys)

# ========== 新闻缓存管理器 ==========
class NewsCache:
    """新闻缓存管理器"""

    def __init__(self, use_redis: bool = False):
        self.memory = MemoryCache(default_ttl=300)
        self.redis = RedisCache() if use_redis else None
        self.use_redis = use_redis and self.redis and self.redis.available

    def get_news(self, key: str = 'latest') -> Optional[List[Dict]]:
        """获取缓存的新闻"""
        # 先查内存
        news = self.memory.get(key)
        if news:
            return news

        # 再查 Redis
        if self.use_redis:
            news = self.redis.get(f'news:{key}')
            if news:
                # 回填内存缓存
                self.memory.set(key, news)
                return news

        return None

    def set_news(self, news: List[Dict], key: str = 'latest', ttl: int = 300):
        """缓存新闻"""
        self.memory.set(key, news, ttl)

        if self.use_redis:
            self.redis.set(f'news:{key}', news, ttl)

    def get_sentiment(self) -> Optional[Dict]:
        """获取情感分析缓存"""
        return self.memory.get('sentiment')

    def set_sentiment(self, data: Dict, ttl: int = 600):
        """缓存情感分析"""
        self.memory.set('sentiment', data, ttl)

    def get_hot_topics(self) -> Optional[List[Dict]]:
        """获取热点话题缓存"""
        return self.memory.get('hot_topics')

    def set_hot_topics(self, topics: List[Dict], ttl: int = 600):
        """缓存热点话题"""
        self.memory.set('hot_topics', topics, ttl)

    def get_source_status(self, source: str) -> Optional[Dict]:
        """获取来源状态缓存"""
        return self.memory.get(f'source:{source}')

    def set_source_status(self, source: str, status: Dict, ttl: int = 60):
        """缓存来源状态"""
        self.memory.set(f'source:{source}', status, ttl)

    def invalidate(self, key: str = None):
        """失效缓存"""
        if key:
            self.memory.delete(key)
            if self.use_redis:
                self.redis.delete(f'news:{key}')
        else:
            self.memory.clear()
            if self.use_redis:
                self.redis.clear()

    def stats(self) -> Dict:
        """缓存统计"""
        result = {
            'memory': self.memory.stats(),
            'redis': self.use_redis
        }
        return result

    def cleanup(self):
        """清理过期缓存"""
