#!/usr/bin/env python3
"""NewsHub Web Dashboard v3.0 - Flask 后端"""
import sys; sys.stdout.reconfigure(encoding='utf-8')
from flask import Flask, jsonify, request, render_template_string
from flask_cors import CORS
import json
from datetime import datetime, timedelta
from pathlib import Path

app = Flask(__name__)
CORS(app)

# ========== 模板 ==========
DASHBOARD_HTML = """
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>NewsHub Dashboard</title>
    <script src="https://cdn.jsdelivr.net/npm/vue@3"></script>
    <script src="https://cdn.jsdelivr.net/npm/axios/dist/axios.min.js"></script>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0f0f1a; color: #e0e0e0; min-height: 100vh; }
        .container { max-width: 1400px; margin: 0 auto; padding: 20px; }
        h1 { font-size: 28px; margin-bottom: 20px; color: #00d4aa; }
        h2 { font-size: 20px; margin: 20px 0 15px; color: #00d4aa; }

        /* Stats Grid */
        .stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; margin-bottom: 20px; }
        .stat-card { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%); border-radius: 12px; padding: 20px; border: 1px solid #2a2a4a; }
        .stat-card .value { font-size: 32px; font-weight: bold; color: #00d4aa; }
        .stat-card .label { font-size: 14px; color: #888; margin-top: 5px; }

        /* News List */
        .news-list { background: #1a1a2e; border-radius: 12px; overflow: hidden; }
        .news-item { padding: 15px 20px; border-bottom: 1px solid #2a2a4a; cursor: pointer; transition: background 0.2s; }
        .news-item:hover { background: #222244; }
        .news-item:last-child { border-bottom: none; }
        .news-title { font-size: 15px; margin-bottom: 8px; }
        .news-meta { font-size: 13px; color: #888; display: flex; gap: 15px; }
        .news-source { color: #00d4aa; }
        .news-category { background: #2a2a4a; padding: 2px 8px; border-radius: 4px; font-size: 12px; }
        .news-score.positive { color: #4caf50; }
        .news-score.negative { color: #f44336; }

        /* Search */
        .search-box { margin-bottom: 20px; }
        .search-box input { width: 100%; max-width: 500px; padding: 12px 15px; border-radius: 8px; border: 1px solid #2a2a4a; background: #1a1a2e; color: #e0e0e0; font-size: 14px; }
        .search-box input:focus { outline: none; border-color: #00d4aa; }

        /* Charts */
        .chart-container { background: #1a1a2e; border-radius: 12px; padding: 20px; margin-bottom: 20px; }
        .bar-chart { display: flex; align-items: flex-end; gap: 5px; height: 150px; }
        .bar { flex: 1; background: linear-gradient(to top, #00d4aa, #00a080); border-radius: 4px 4px 0 0; min-height: 5px; position: relative; }
        .bar:hover { background: linear-gradient(to top, #00ffcc, #00d4aa); }
        .bar-label { position: absolute; bottom: -25px; left: 50%; transform: translateX(-50%); font-size: 11px; color: #888; white-space: nowrap; }

        /* Navigation */
        nav { display: flex; gap: 10px; margin-bottom: 20px; }
        nav button { padding: 10px 20px; border-radius: 8px; border: none; background: #2a2a4a; color: #e0e0e0; cursor: pointer; transition: all 0.2s; }
        nav button:hover { background: #3a3a5a; }
        nav button.active { background: #00d4aa; color: #000; }

        /* Responsive */
        @media (max-width: 768px) {
            .container { padding: 10px; }
            .stats-grid { grid-template-columns: repeat(2, 1fr); }
        }
    </style>
</head>
<body>
    <div id="app" class="container">
        <h1>📰 NewsHub Dashboard</h1>

        <!-- Stats -->
        <div class="stats-grid">
            <div class="stat-card">
                <div class="value">{{ stats.total || 0 }}</div>
                <div class="label">总新闻</div>
            </div>
            <div class="stat-card">
                <div class="value">{{ stats.sentiment?.positive || 0 }}</div>
                <div class="label">🟢 利好</div>
            </div>
            <div class="stat-card">
                <div class="value">{{ stats.sentiment?.negative || 0 }}</div>
                <div class="label">🔴 利空</div>
            </div>
            <div class="stat-card">
                <div class="value">{{ stats.sentiment?.neutral || 0 }}</div>
                <div class="label">⚪ 中性</div>
            </div>
        </div>

        <!-- Navigation -->
        <nav>
            <button :class="{ active: view === 'latest' }" @click="view = 'latest'">最新</button>
            <button :class="{ active: view === 'hot' }" @click="view = 'hot'">热点</button>
            <button :class="{ active: view === 'search' }" @click="view = 'search'">搜索</button>
            <button :class="{ active: view === 'sources' }" @click="view = 'sources'">来源</button>
        </nav>

        <!-- Search -->
        <div v-if="view === 'search'" class="search-box">
            <input v-model="searchQuery" @keyup.enter="doSearch" placeholder="搜索新闻...">
        </div>

        <!-- Latest News -->
        <div v-if="view === 'latest'">
            <h2>📰 最新新闻</h2>
            <div class="news-list">
                <div v-for="news in newsList" :key="news.id" class="news-item" @click="openNews(news)">
                    <div class="news-title">{{ news.title }}</div>
                    <div class="news-meta">
                        <span class="news-source">{{ news.source }}</span>
                        <span class="news-category">{{ news.category }}</span>
                        <span :class="['news-score', news.score > 20 ? 'positive' : news.score < -20 ? 'negative' : '']">
                            评分: {{ news.score }}
                        </span>
                    </div>
                </div>
            </div>
        </div>

        <!-- Hot Topics -->
        <div v-if="view === 'hot'">
            <h2>🔥 热点话题</h2>
            <div class="chart-container">
                <div class="bar-chart">
                    <div v-for="(topic, i) in hotTopics.slice(0, 10)" :key="i" class="bar" :style="{ height: (topic.count / maxCount * 100) + '%' }">
                        <div class="bar-label">{{ topic.word }}</div>
                    </div>
                </div>
            </div>
        </div>

        <!-- Sources -->
        <div v-if="view === 'sources'">
            <h2>📰 新闻来源</h2>
            <div class="chart-container">
                <div class="bar-chart">
                    <div v-for="(count, source) in stats.by_source" :key="source" class="bar" :style="{ height: (count / maxSourceCount * 100) + '%' }">
                        <div class="bar-label">{{ source }}</div>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        const { createApp } = Vue;

        createApp({
            data() {
                return {
                    view: 'latest',
                    stats: {},
                    newsList: [],
                    hotTopics: [],
                    searchQuery: ''
                };
            },
            computed: {
                maxCount() {
                    return Math.max(...this.hotTopics.map(t => t.count), 1);
                },
                maxSourceCount() {
                    return Math.max(...Object.values(this.stats.by_source || {}), 1);
                }
            },
            methods: {
                async loadStats() {
                    const res = await axios.get('/api/stats');
                    this.stats = res.data;
                },
                async loadNews() {
                    const res = await axios.get('/api/news?limit=50');
                    this.newsList = res.data;
                },
                async loadHotTopics() {
                    const res = await axios.get('/api/hot');
                    this.hotTopics = res.data;
                },
                async doSearch() {
                    if (!this.searchQuery) return;
                    const res = await axios.get('/api/search?q=' + this.searchQuery);
                    this.newsList = res.data;
                },
                openNews(news) {
                    if (news.url) window.open(news.url, '_blank');
                }
            },
            watch: {
                view(v) {
                    if (v === 'latest') this.loadNews();
                    else if (v === 'hot') this.loadHotTopics();
                }
            },
            mounted() {
                this.loadStats();
                this.loadNews();
            }
        }).mount('#app');
    </script>
</body>
</html>
"""

# ========== API 路由 ==========
@app.route('/')
def index():
    return render_template_string(DASHBOARD_HTML)

@app.route('/api/stats')
def api_stats():
    from database import db
    return jsonify(db.get_stats())

@app.route('/api/news')
def api_news():
    from database import db
    limit = int(request.args.get('limit', 50))
    source = request.args.get('source')
    category = request.args.get('category')

    news = db.get_news(limit=limit, source=source, category=category)
    return jsonify(news)

@app.route('/api/news/<int:news_id>')
def api_news_detail(news_id):
    from database import db
    conn = db._get_conn()
    c = conn.cursor()
    c.execute('SELECT * FROM news WHERE id = ?', (news_id,))
    row = c.fetchone()
    conn.close()

    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/search')
def api_search():
    from database import db
    q = request.args.get('q', '')
    limit = int(request.args.get('limit', 50))

    if not q:
        return jsonify([])

    return jsonify(db.search(q, limit))

@app.route('/api/hot')
def api_hot():
    from database import db
    return jsonify(db.get_top_keywords(20))

@app.route('/api/sources')
def api_sources():
    from database import db
    return jsonify(db.get_sources())

@app.route('/api/fetch', methods=['POST'])
def api_fetch():
    """触发抓取"""
    from async_fetcher import fetch_all
    news = fetch_all(quiet=True)
    return jsonify({'fetched': len(news)})

@app.route('/api/notifications')
def api_notifications():
    from database import db
    days = int(request.args.get('days', 7))
    return jsonify(db.get_notifications(days))

# ========== 启动 ==========
def run_dashboard(port=8450):
    print(f"""
  ╔════════════════════════════════════════════════╗
  ║  📰 NewsHub Dashboard v3.0                           ║
  ╠════════════════════════════════════════════════╣
  ║  地址: http://localhost:{port}                        ║
  ║  API:  http://localhost:{port}/api/stats              ║
  ╚════════════════════════════════════════════════╝
    """)
    app.run(host='0.0.0.0', port=port, debug=False)

if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--port', type=int, default=8450)
    args = parser.parse_args()

    run_dashboard(args.port)

