            </div>
            <div class="stat-card">
                <div class="value">{{ stats.sentiment?.negative || 0 }}</div>
                <div class="label">🔴 利空</div>
            </div>
            <div class="stat-card">
                <div class="value">{{ stats.sentiment?.neutral || 0 }}</div>
                <div class="label">⚪ 中性</div>
            </div>
        </div>

        <!-- Navigation -->
        <nav>
            <button :class="{ active: view === 'latest' }" @click="view = 'latest'">最新</button>
            <button :class="{ active: view === 'hot' }" @click="view = 'hot'">热点</button>
            <button :class="{ active: view === 'search' }" @click="view = 'search'">搜索</button>
            <button :class="{ active: view === 'sources' }" @click="view = 'sources'">来源</button>
