    name: str
    enabled: bool = True
    channel_type: str = ''  # feishu/qq/wechat/telegram/discord/slack/email/webhook
    config: Dict = None  # 渠道特定配置

    def __post_init__(self):
        if self.config is None:
            self.config = {}

