class PushManager:
    """统一推送管理器"""

    def __init__(self):
        self.config_file = Path(__file__).parent / 'push_config.json'
        self.config = self._load_config()
        self.results: List[PushResult] = []

    def _load_config(self) -> Dict:
        """加载配置"""
        if self.config_file.exists():
            with open(self.config_file, 'r', encoding='utf-8') as f:
                return json.load(f)

        # 默认配置
        return {
            'channels': {
                'feishu': {'enabled': True, 'mode': 'digest'},
                'qq': {'enabled': False},
