                'telegram': {'enabled': False},
                'discord': {'enabled': False},
                'slack': {'enabled': False},
                'email': {'enabled': False},
                'webhook': {'enabled': False}
            },
            'settings': {
                'parallel': False,  # 并行推送
                'stop_on_error': True,
                'retry': 2,
                'retry_delay': 3
            }
        }

