    def _load_cache(self) -> Dict:
        cache_file = f'.ai_cache_{self.model}.json'
        try:
            with open(cache_file, 'r', encoding='utf-8') as f:
                return json.load(f)
        except:
            return {}

    def _save_cache(self):
        cache_file = f'.ai_cache_{self.model}.json'
        with open(cache_file, 'w', encoding='utf-8') as f:
            json.dump(self.cache, f, ensure_ascii=False, indent=2)

    def _get_cache_key(self, title: str) -> str:
        simplified = re.sub(r'[^\w\u4e00-\u9fff]', '', title.lower())[:50]
        return hashlib.md5(simplified.encode()).hexdigest()[:16]

    def analyze(self, title: str, content: str = '') -> AnalysisResult:
        """分析单条新闻"""
        key = self._get_cache_key(title)
        if key in self.cache:
            cached = self.cache[key]
            if time.time() - cached.get('cached_at', 0) < 86400:
                return AnalysisResult(**cached['result'])

        result = self._rule_based_analysis(title, content)

        self.cache[key] = {
            'result': result.to_dict(),
            'cached_at': time.time()
        }
        if len(self.cache) > 500:
            sorted_keys = sorted(self.cache.items(), key=lambda x: x[1]['cached_at'])
            for k, _ in sorted_keys[:100]:
                del self.cache[k]
        self._save_cache()

        return result

    def _rule_based_analysis(self, title: str, content: str = '') -> AnalysisResult:
        """基于规则的分析"""
        text = (title + ' ' + content).lower()

        positive_words = ['涨', '利好', '突破', '新高', '增长', '盈利', '上涨', '牛市', 
                         'surge', 'rise', 'gain', 'bull', 'rally', 'soar', 'jump', 'beat']
        negative_words = ['跌', '利空', '崩盘', '危机', '亏损', '下跌', '熊市', 
                         'crash', 'fall', 'drop', 'bear', 'plunge', 'sink', 'miss', 'loss']

        positive_count = sum(1 for w in positive_words if w in text)
        negative_count = sum(1 for w in negative_words if w in text)

        sentiment = 0
        if positive_count > negative_count:
            sentiment = min(50 + (positive_count - negative_count) * 10, 100)
        elif negative_count > positive_count:
            sentiment = max(-50 - (negative_count - positive_count) * 10, -100)

        if sentiment > 20:
            sentiment_label = 'bullish'
        elif sentiment < -20:
            sentiment_label = 'bearish'
        else:
            sentiment_label = 'neutral'

        market_impact = 'none'
        if any(w in text for w in ['股票', '指数', '美股', 'nasdaq', 'dow']):
            market_impact = 'stock'
        elif any(w in text for w in ['crypto', 'bitcoin', 'btc', 'eth', '加密']):
            market_impact = 'crypto'
        elif any(w in text for w in ['原油', 'oil', '黄金', 'gold', '商品']):
            market_impact = 'commodity'
        elif any(w in text for w in ['fed', '利率', '美债', '美联储']):
            market_impact = 'bond'
        elif any(w in text for w in ['外汇', '美元', '人民币', '汇率']):
            market_impact = 'forex'

        importance = 'medium'
        if any(w in text for w in ['崩盘', '危机', 'crash', 'war', '降息', '升息']):
            importance = 'critical'
        elif any(w in text for w in ['cpi', 'pce', 'nfp', '关税', 'nvidia']):
            importance = 'high'

        risk_level = 'high' if importance == 'critical' else 'medium' if abs(sentiment) > 30 else 'low'

        advice = 'buy' if sentiment > 40 else 'sell' if sentiment < -40 else 'watch' if sentiment > 10 else 'hold'

        entities = []
        for match in re.findall(r'([A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)*)', title):
            if len(match) > 2 and len(entities) < 5:
                entities.append(match)

        emoji = {'bullish': '📈', 'bearish': '📉', 'neutral': '➡️'}.get(sentiment_label, '➡️')
        market_map = {'stock': '股市', 'crypto': '加密', 'forex': '外汇', 'commodity': '商品', 'bond': '债券', 'none': '市场'}
        market_name = market_map.get(market_impact, '市场')

        if sentiment_label == 'bullish':
            summary = f"{emoji} {market_name}利好，关注上涨机会"
        elif sentiment_label == 'bearish':
            summary = f"{emoji} {market_name}利空，注意风险"
        else:
            summary = f"{emoji} {market_name}中性，观望为主"

        return AnalysisResult(
            title=title, summary=summary, sentiment=sentiment, sentiment_label=sentiment_label,
            market_impact=market_impact, importance=importance, entities=entities[:5],
            advice=advice, risk_level=risk_level, time_horizon='short',
            reasoning=f"关键词分析: {positive_count}正面/{negative_count}负面"
        )

    def analyze_batch(self, news: List[Dict], callback: Callable = None) -> List[Dict]:
        """批量分析"""
        results = []
        total = len(news)

        for i, item in enumerate(news):
            result = self.analyze(item.get('title', ''), item.get('content', ''))
            item.update(result.to_dict())
            results.append(item)

            if callback:
                callback(i + 1, total, item['title'][:30])

        return results

    def get_market_sentiment(self, news: List[Dict]) -> Dict:
        """计算市场情绪"""
        if not news:
            return {'score': 0, 'label': 'neutral', 'distribution': {}}

        sentiments = [item.get('sentiment', 0) for item in news]
        avg = sum(sentiments) / len(sentiments) if sentiments else 0

        label = 'bullish' if avg > 15 else 'bearish' if avg < -15 else 'neutral'

        return {
            'score': round(avg, 1),
            'label': label,
            'distribution': {
                'positive': sum(1 for s in sentiments if s > 20),
                'neutral': sum(1 for s in sentiments if -20 <= s <= 20),
                'negative': sum(1 for s in sentiments if s < -20)
            }
        }

    def clear_cache(self):
        self.cache = {}
        self._save_cache()
        print("  ✓ 缓存已清空")

